const isOpened=(c,student='m1')=>owned(student).some(a=>a.courseId===c.id&&['active','submitted'].includes(a.status));
function header(title,back='home'){return `<header class="app-bar">${back?`<button class="back" data-go="${back}" ${role==='student'&&learningBackPages.includes(page)?'data-history-back':''} aria-label="返回">${icon('left')}</button>`:'<span style="width:28px" aria-hidden="true"></span>'}<div class="bar-title">${esc(title)}</div><span style="width:28px" aria-hidden="true"></span></header>`;}
function bottom(active){const student=role!=='teacher',items=student?[['home','book','修学'],['journey','clock','历程'],['profile','user','我的']]:[['students','users','学员'],['arrangement-history','book','安排记录'],['profile','user','我的']];return `<nav class="bottom-nav${student?' student-tabbar':''}" aria-label="主导航">${items.map(([to,ic,label])=>`<button data-go="${to}" class="${active===to?'active':''}" ${active===to?'aria-current="page"':''}>${student?'':icon(ic)}<span>${label}</span></button>`).join('')}</nav>`;}
const primary=(text,action,disabled=false)=>`<button class="primary" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const foot=(text,action,note='',disabled=false)=>`<footer class="action-footer">${primary(text,action,disabled)}${note?`<p>${note}</p>`:''}</footer>`;
const row=(to,title,desc,ic='book',attrs='')=>`<button class="list-row" data-go="${to}" ${attrs}><span class="row-icon">${icon(ic)}</span><span class="row-main"><strong>${esc(title)}</strong><small>${esc(desc)}</small></span>${icon('right','row-arrow')}</button>`;
const notice=(title,text)=>`<div class="definition-notice"><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`;
const list=items=>`<ul class="pending-list">${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;
function openInfo(title,body){ui.modal='info';ui.infoTitle=title;ui.infoBody=body;render(true);}
function setToast(text,ms=2800){ui.toast=text;setTimeout(()=>{if(ui.toast!==text)return;ui.toast='';$('.toast')?.remove();},ms);}
function flash(text){setToast(text);render(true);}
function branchOf(a){return courseById(a?.courseId)?.branch;}
function lotusState(name){const arr=owned().filter(a=>name==='正见'||branchOf(a)===name),active=arr.filter(a=>['active','submitted'].includes(a.status));return {arr,active,label:name==='正见'?`${active.length}门理论`:active.length?`${active.length}门已安排`:'待安排'};}
function resumeStudy(){
 const saved=data.lastStudy,positions=owned().map(a=>({a,position:actualStudyPosition(a)})).filter(x=>x.position),latest=positions.find(x=>x.a.id===saved?.assignmentId&&['article','reflect'].includes(saved.page))||positions.sort((a,b)=>(Date.parse(b.position.at)||0)-(Date.parse(a.position.at)||0))[0];
 if(latest)return {a:latest.a,page:latest.position.page,hasHistory:true};
 return {a:owned().find(a=>a.status==='active'),page:'task',hasHistory:false};
}
function categoryCourses(branch){return COURSES.filter(c=>c.branch===branch);}
function home(){const unread=noticeItems().filter(n=>n.unread).length,resume=resumeStudy(),a=resume.a,phase={task:'课程学习',read:'闻',article:'闻',think:'思',reflect:'思',practice:'修'},resumeDetail={article:'闻 · 文章阅读',reflect:'思 · 反思记录'}[resume.page]||phase[resume.page];return {
 bar:`<header class="app-bar home-app-bar"><h1 class="home-page-title">我的修学</h1><button class="icon-btn notification-bell" data-action="notices" aria-label="修学消息${unread?'，'+unread+'条未读':''}">${icon('bell')}${unread?'<span class="notification-dot" aria-hidden="true"></span>':''}</button></header>`,
 body:`<div class="lotus-home"><section class="home-lotus-hero" aria-label="五正修学入口">${studyLotus()}<p class="home-lotus-hint">点击花瓣进入类别</p></section><div class="home-study-sheet"><section class="resume-section" aria-label="${resume.hasHistory?'继续上次学习':'开始学习'}"><h2 class="home-section-title">${resume.hasHistory?'继续学习':'开始学习'}</h2>${a?`<button class="resume-entry" data-go="${resume.page}" data-id="${esc(a.id)}" aria-label="${resume.hasHistory?'继续学习':'开始学习'}，${esc(courseById(a.courseId).title)}${resume.hasHistory?'，上次停在：'+resumeDetail:''}"><span class="resume-entry-copy"><strong>${esc(courseById(a.courseId).title)}</strong>${resume.hasHistory?`<small class="resume-position">${resumeDetail}</small>`:'<small>法师已安排，可开始学习</small>'}</span><span class="resume-entry-action" aria-hidden="true">${icon('arrow')}</span></button>`:`<div class="home-empty"><h3>暂无已安排课程</h3><p>法师安排后，可从这里开始学习。</p><button class="text-button" data-go="guide">先看公共导读 ${icon('right')}</button></div>`}</section></div></div>`,bottom:bottom('home')};}
function category(){
 const branch=ui.categoryBranch,theory=branch==='正见',items=categoryCourses(branch);
 const assigned=theory?owned().filter(a=>['active','submitted'].includes(a.status)):items.map(c=>owned().find(a=>a.courseId===c.id&&['active','submitted'].includes(a.status))).filter(Boolean);
 const locked=theory?[]:items.filter(c=>!isOpened(c));
 const title=theory?'正见 · 理论学习':branch+'课程';
 return {bar:header(title,'home').replace(`<div class="bar-title">${title}</div>`,`<h1 class="bar-title">${title}</h1>`),body:`<div class="pad category-page"><p class="sub category-intro">${theory?'正见为“解”，汇总已开放课程的讲解资料。':'本类别共'+items.length+'门课程，由法师按个人情况安排。'}</p><section aria-label="${theory?'已开放的理论':'已安排课程'}"><div class="section-title"><h2>${theory?'已开放的理论':'已安排'}</h2><span class="sub">${assigned.length}门</span></div>${assigned.length?assigned.map(a=>`<button class="category-assignment" data-go="${theory?'read':'task'}" data-id="${a.id}"><span><strong>${esc(courseById(a.courseId).title)}</strong><small>${theory?esc(branchOf(a))+'课 · 讲解资料待接入':status(a)}</small></span>${icon('right')}</button>`).join(''):`<div class="category-empty"><p>${theory?'暂未开放课程理论':'这个类别暂未安排课程'}</p><small>${theory?'法师开放课程后，对应理论会汇总到这里。':'可以浏览下方课程名称，等待法师安排。'}</small></div>`}</section>${theory?'<p class="plain-note">理论资料随课程开放，不另外增加一套课程。</p>':`<section class="category-unassigned" aria-label="未安排课程"><div class="section-title"><h2>未安排</h2><span class="sub">${locked.length}门</span></div>${locked.length?`<div class="catalog-grid">${locked.map(c=>`<button class="catalog-course locked" data-go="course" data-course="${c.id}" data-from="category"><strong>${esc(c.title)}</strong><span>${icon('lock')}未安排</span></button>`).join('')}</div><p class="plain-note">未安排课程可查看名称与开放说明，学习内容仍需法师开放。</p>`:'<p class="plain-note">本类别课程均已安排。</p>'}</section>`}</div>`,bottom:bottom('home')};
}
function pairing(c){return `<section class="course-pairing"><div class="section-title"><h2>正见 · 理论范围</h2><span class="tag gray">解</span></div><p class="source-path">${c.theoryPath.map(esc).join(' → ')}</p><p class="plain-note">本课讲解资料与必学范围待接入，不编写替代讲义。</p><div class="section-title"><h2>${esc(c.branch)} · 行门配套</h2><span class="tag gray">行</span></div>${c.checks.length?`<div class="confirmed-pairing"><strong>课程初稿已明确对应</strong>${list(c.checks)}<p>以上自检归“思”；具体表单、必填与完成规则仍待确认。</p></div>`:'<p class="sub">本课尚无已确认的具体配套。</p>'}${c.practices.length?list(c.practices):''}${notice('待法师确认',c.pending.join('；'))}<p class="plain-note">修的范围尚待确认，不预设念佛次数、拜数、周期或统一完成分数。没有独立实践的课程，不强行添加“修”。</p></section>`;}
function course(){const c=courseById(courseId),opened=isOpened(c),existing=owned(role==='teacher'?activeStudent:'m1').find(a=>a.courseId===c.id&&['active','submitted'].includes(a.status));const locked=role==='student'&&!opened;return {bar:header(role==='teacher'?'固定课程配置':'课程详情',role==='teacher'?'assign':ui.courseFrom),body:`<div class="pad"><div class="breadcrumb">${esc(c.branch)}课 · 四类24门</div><h1 class="detail-title">${esc(c.title)}</h1>${locked?`${notice('尚未安排 · 内容锁定','当前仅展示课程名称。讲解资料、自检与实践须由法师开放课程后进入。')}<p class="plain-note">请按法师当前安排修学。公共导读可随时查看。</p>`:`${notice('课程配套待法师确认','这是课程设计预览。已明确的对应关系与待确认配套分开列出；日常安排不逐张选择表单。')}${pairing(c)}`}${role==='teacher'?row('directory','核对完整行门目录','保留原图归属；未绑定的内容不会默认开放','list'):''}</div>`,footer:role==='teacher'?foot(existing?'本课已安排':'加入本次安排','choose-course','当前发布为演示安排，未确认配置不能判定完成。',!!existing):opened?`<footer class="action-footer"><button class="primary" data-go="task" data-id="${existing.id}">进入已安排课程</button></footer>`:foot('课程尚未开放','locked','由法师决定开放哪门或多门课程。',true)};}
function task(){const a=current(),c=courseById(a.courseId);return {bar:header('课程学习',ui.taskFrom),body:`<div class="pad"><div class="breadcrumb">${esc(c.branch)}课</div><h1 class="detail-title">${esc(c.title)}</h1>${tag(a)}<div class="guidance"><div class="guidance-head">慧明法师 · 本次指导（演示）</div><p>${esc(a.guidance)}</p>${a.requirements?`<p class="space-top-sm">本次要求：${esc(a.requirements)}</p>`:''}</div><section class="stage-block"><div class="stage-head"><span class="stage-symbol">闻</span><h2>讲解资料</h2><small>待接入</small></div>${row('read',c.title+'讲解资料','按正见原图路径归档')}</section><section class="stage-block"><div class="stage-head"><span class="stage-symbol">思</span><h2>自检与反思</h2><small>${a.reflectionAt?'心得已保存':'可记录心得'}</small></div>${row('think','专项自检、心得与问题',c.checks.length?c.checks.join('、'):'自检配套待法师确认','edit')}</section><section class="stage-block"><div class="stage-head"><span class="stage-symbol">修</span><h2>配套实践</h2><small>待确认</small></div>${row('practice','查看本课实践范围','待法师确认，不强加独立实践','lotus')}</section>${notice('本课配套仍待确认','可以查看结构、记录心得与问题。真实资料、表单和完成要求齐备前，不生成已学完结果。')}${row('course','查看本课固定配置','理论与行门配套、待确认内容','list',`data-course="${c.id}"`)}${row('records','本课学习记录','回看安排、心得与指导','clock',`data-id="${a.id}"`)}</div>`,footer:foot('查看提交要求','open-submit')};}
function read(){const c=courseById(current().courseId);return {bar:header('闻 · 讲解资料',ui.readFrom),body:`<div class="pad"><h1 class="detail-title">${esc(c.title)}</h1><p class="source-path">${c.theoryPath.map(esc).join(' → ')}</p>${notice('正式讲解资料待接入','先体验文章阅读流程。演示样稿不代表本课正式教材，课程配套与完成要求仍待确认。')}<div class="section-title"><h2>本次学习</h2></div>${row('article','开始学习','进入演示文章 · 自动计时、翻页与书签','book')}<p class="plain-note">此页不计时。进入正文后自动记录演示阅读时长，进度与时长在历程中标注演示，不计入正式修学累计。</p></div>`,footer:foot(ui.readFrom==='category'?'返回正见':'返回课程',ui.readFrom==='category'?'return-category':'return-task')};}
function prepareArticle(){if(role==='student'&&page==='article'&&current()?.status==='active'){T.openDemo(data.tools,current().id,DEMO_ARTICLE.title,DEMO_ARTICLE.pages.length);persist();}}
const READER_FONTS={serif:'"Songti SC","Noto Serif SC",SimSun,serif',sans:'-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif',kai:'"Kaiti SC",STKaiti,KaiTi,"Songti SC",serif'};
function readerTextStyle(){const r=data.tools.reader;return `font-family:${esc(READER_FONTS[r.fontFamily]||READER_FONTS.serif)};font-size:${r.fontSize}px;line-height:${r.lineHeight}`;}
function isReaderPanel(){return ['reader-settings','reader-directory','reader-bookmarks'].includes(ui.modal);}
function readerFooter(index,total,isArticle){return `<footer class="reader-footer"><div class="reader-pagination"><button class="text-button" data-action="${isArticle?'article-turn':'text-prev'}" ${isArticle?`data-page="${index-1}"`:''} ${index===0?'disabled':''}>${icon('left')} 上一${isArticle?'节':'页'}</button><span>${index+1} / ${total}</span>${isArticle&&index===total-1?'<button class="text-button" data-action="article-reflect">写心得 '+icon('edit')+'</button>':`<button class="text-button" data-action="${isArticle?'article-turn':'text-next'}" ${isArticle?`data-page="${index+1}"`:''} ${index===total-1?'disabled':''}>下一${isArticle?'节':'页'} ${icon('right')}</button>`}</div><nav class="reader-toolbar" aria-label="阅读工具"><button id="reader-open-directory" data-action="open-reader-panel" data-panel="directory">${icon('list')}<span>${isArticle?'目录':'页码'}</span></button><button id="reader-open-bookmarks" data-action="open-reader-panel" data-panel="bookmarks">${icon('bookmark')}<span>书签</span></button><button id="reader-open-settings" data-action="open-reader-panel" data-panel="settings"><span class="reader-type-icon" aria-hidden="true">Aa</span><span>阅读设置</span></button></nav></footer>`;}
function article(){const a=current(),c=courseById(a.courseId),d=data.tools.demoReadings[a.id]||{page:0,bookmarks:[]},section=DEMO_ARTICLE.pages[d.page];return {bar:header('闻 · 文章阅读',ui.articleFrom),body:`<div class="pad demo-article"><div class="demo-article-label"><span>原型演示</span><small>通用样稿 · 正式教材待接入</small></div><p class="article-course">${esc(c.title)} · 闻 · ${d.page+1}/${DEMO_ARTICLE.pages.length}节</p><h1 class="article-title">${DEMO_ARTICLE.title}</h1><article class="demo-article-body" style="${readerTextStyle()}"><h2>${section.title}</h2>${section.paragraphs.map(p=>`<p>${p}</p>`).join('')}</article>${d.page===DEMO_ARTICLE.pages.length-1?'<p class="plain-note">读到这里，可以写下心得或想请教的问题，也可以直接返回。阅读时长会自动记录；本篇样稿不代表课程完成。</p>':''}</div>`,footer:readerFooter(d.page,DEMO_ARTICLE.pages.length,true)};}
function readerPreferenceButton(key,value,label){const selected=data.tools.reader[key]===value;return `<button id="reader-pref-${key}-${value}" data-action="reader-preference" data-setting="${key}" data-value="${value}" aria-pressed="${selected}" ${key==='fontFamily'?`style="font-family:${esc(READER_FONTS[value])}"`:''}>${label}</button>`;}
function readerSettingsPanel(){const r=data.tools.reader;return `<div class="reader-settings-panel"><div class="reader-font-preview" style="${readerTextStyle()}">静下心来，读好当下一段。</div><fieldset class="reader-option-group"><legend>字体</legend><div class="reader-segments">${[['serif','宋体'],['sans','黑体'],['kai','楷体']].map(([v,label])=>readerPreferenceButton('fontFamily',v,label)).join('')}</div></fieldset><fieldset class="reader-option-group"><legend>字号</legend><div class="reader-size-stepper"><button id="reader-font-smaller" data-action="reader-preference" data-setting="fontSize" data-value="${r.fontSize-2}" aria-label="减小字号" ${r.fontSize<=16?'disabled':''}>A−</button><output aria-live="polite">${r.fontSize}</output><button id="reader-font-larger" data-action="reader-preference" data-setting="fontSize" data-value="${r.fontSize+2}" aria-label="增大字号" ${r.fontSize>=28?'disabled':''}>A＋</button></div></fieldset><fieldset class="reader-option-group"><legend>行距</legend><div class="reader-segments">${[[1.7,'紧凑'],[1.9,'标准'],[2.2,'宽松']].map(([v,label])=>readerPreferenceButton('lineHeight',v,label)).join('')}</div></fieldset><fieldset class="reader-option-group"><legend>背景</legend><div class="reader-theme-options">${[['paper','纸色'],['white','白色'],['green','护眼绿'],['night','夜间']].map(([v,label])=>`<button id="reader-pref-theme-${v}" data-action="reader-preference" data-setting="theme" data-value="${v}" aria-pressed="${r.theme===v}"><span class="reader-swatch swatch-${v}" aria-hidden="true">${r.theme===v?icon('check'):''}</span><span>${label}</span></button>`).join('')}</div></fieldset><div class="reader-settings-end"><small>自动保存到本机</small><button id="reader-reset-style" class="text-button" data-action="reset-reader-preferences">恢复默认</button></div>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}</div>`;}
function readerNavigationPanel(bookmarks=false){const isArticle=page==='article',d=isArticle?data.tools.demoReadings[current()?.id]:data.tools.reader.document;if(!d)return '<p class="plain-note">暂无可阅读内容。</p>';const total=isArticle?DEMO_ARTICLE.pages.length:T.pages(d.text).length,unit=isArticle?'节':'页',items=isArticle?DEMO_ARTICLE.pages.map((p,i)=>({page:i,title:p.title})):[];
 if(bookmarks)return `<button class="reader-bookmark-toggle" data-action="toggle-reader-bookmark">${icon('bookmark')}${d.bookmarks.includes(d.page)?'移除当前'+unit+'书签':'添加当前'+unit+'书签'}</button>${d.bookmarks.length?`<nav class="reader-panel-list" aria-label="已保存书签">${d.bookmarks.map(i=>`<button data-action="${isArticle?'article-turn':'reader-bookmark-jump'}" data-page="${i}"><span>第${i+1}${unit}${isArticle?' · '+DEMO_ARTICLE.pages[i].title:''}</span>${icon('right')}</button>`).join('')}</nav>`:'<p class="plain-note">暂无书签。读到想回看的地方，可以添加书签。</p>'}`;
 return isArticle?`<p class="reader-panel-note">${DEMO_ARTICLE.title} · ${total}节</p><nav class="reader-panel-list" aria-label="演示文章目录">${items.map(item=>`<button data-action="article-turn" data-page="${item.page}" ${item.page===d.page?'aria-current="page"':''}><span><small>第${item.page+1}节</small>${item.title}</span>${item.page===d.page?'<em>正在读</em>':icon('right')}</button>`).join('')}</nav>`:`<p class="reader-panel-note">共${total}页 · 当前第${d.page+1}页</p><div class="reader-jump"><label for="reader-jump">跳至</label><input id="reader-jump" type="number" min="1" max="${total}" value="${d.page+1}" aria-label="跳至页码"><span>页</span><button class="small-primary" data-action="reader-jump">跳转</button></div><p class="plain-note">个人TXT按文本分页，暂不生成章节目录。</p>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}`;
}
function closeModal(){const panel=isReaderPanel()?ui.modal.replace('reader-',''):null;ui.modal=null;ui.error='';if(panel)syncLearningTimer();render(true);if(panel)requestAnimationFrame(()=>document.getElementById('reader-open-'+panel)?.focus());}
function finishReaderJump(){if(isReaderPanel()){ui.modal=null;syncLearningTimer();}ui.error='';render();}
function think(){const a=current(),c=courseById(a.courseId);return {bar:header('思 · 自检与反思','task'),body:`<div class="pad"><h1 class="page-heading">自检与反思</h1><p class="sub space-top-sm">${esc(c.title)} · 自检、心得、问题都归“思”</p><div class="section-title"><h2>课程专项自检</h2></div>${c.checks.length?c.checks.map(t=>`<div class="unit-material-preview">${icon('edit')}<span>${esc(t)}</span><small>表单待接入</small></div>`).join(''):notice('自检配套待法师确认','本课未明确自检表，不套用其他课程表单。')}${notice('必填规则与完成要求待确认','真实题目、评分及回向文本未接入。当前目录与说明不计时。本课自检在此查看，表单与要求确认后再开放填写。')}<div class="section-title"><h2>心得与问题</h2></div>${row('reflect',a.reflectionAt?'继续反思':'开始反思','进入心得编辑页后自动记录思考时长','edit')}<p class="plain-note">可以先记录自己的体会与问题；这不替代待接入的专项自检，不生成自检分数或结课结果。</p></div>`,footer:foot('返回课程','return-task')};}
function reflect(){const a=current(),c=courseById(a.courseId),draft=reflectionValues(a),feedback=noticeItems().find(n=>n.assignmentId===a.id&&n.type==='reply'&&n.question===a.question);return {bar:header('思 · 心得与问题',ui.reflectFrom),body:`<div class="pad"><h1 class="page-heading">${esc(c.title)} · 反思</h1><p class="sub space-top-sm">写下自己的体会；离开时自动记录本次反思时长。</p><div class="field"><label for="reflection">我的心得</label><textarea id="reflection" maxlength="1500" placeholder="记录这门课带给你的观察与体会">${esc(draft.text)}</textarea></div><div class="field"><label for="question">想请教法师的问题</label><textarea id="question" maxlength="1000" placeholder="记录需要法师指导的地方">${esc(draft.question)}</textarea></div>${a.question?.trim()?`<p class="reflection-feedback">${feedback?'已保存的问题有法师回复':'已保存的问题 · 等待法师回应'}${feedback?`<button class="text-button" data-action="open-notice" data-notice="${esc(feedback.token)}">查看回复 ${icon('right')}</button>`:''}</p>`:''}<p class="plain-note" id="reflection-save-status" role="status">${a.reflectionDraft?'草稿已暂存本机':a.reflectionAt?'心得与问题已保存':'内容会自动暂存在本机'}</p><p class="plain-note">自检表单与完成要求仍待确认，心得不代表本课已完成。</p>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}</div>`,footer:foot('保存并返回','save-reflection','无需另行结束计时。')};}
function practice(){const c=courseById(current().courseId);return {bar:header('修 · 配套实践','task'),body:`<div class="pad"><h1 class="detail-title">${esc(c.title)} · 实践</h1>${notice('实践配套待法师确认','本课是否有独立实践、具体内容、目标与周期，均须先确认。不默认加入计数念佛、助念或拜佛任务。')}${c.id==='wholehearted'?'<p class="source-note">初稿明确关联“定课自检中的舍命念佛”，该自检归“思”；不据此推定实际实践范围或数量。</p>':''}${list(c.pending)}<div class="section-title"><h2>本课修习</h2></div><button class="primary" data-action="start-practice" disabled>开始修习</button><p class="plain-note">本课实践尚未确认，暂不可开始；此页不计时。独立个人修习可从我的 → 阅读与修学工具进入个人计时。</p><div class="section-title"><h2>个人辅助工具</h2></div>${row('counter','念佛计数','仅保存个人次数，不作为本课已确认配套','lotus')}<p class="plain-note">念佛等持续实践可与课程同时安排。工具不预设次数，是否计入本课要求仍待法师确认。</p></div>`,footer:foot('返回课程','return-task')};}
function submit(){const a=current(),c=courseById(a.courseId);return {bar:header('提交已学完','task'),body:`<div class="pad"><h1 class="detail-title">${esc(c.title)}</h1>${notice('暂不可提交完成','本课固定配套、真实资料和完成要求尚未齐备。已保存心得会保留，但不能据此认定课程已学完。')}<div class="section-title"><h2>尚需补齐</h2></div>${list(definitionGaps(c))}<div class="state-list"><div class="summary-row"><span>闻 · 资料进度</span><span class="value">待接入</span></div><div class="summary-row"><span>思 · 专项自检</span><span class="value">待接入／确认</span></div><div class="summary-row"><span>心得与问题</span><span class="value">${a.reflectionAt?'已保存':'尚未保存'}</span></div><div class="summary-row"><span>修 · 配套实践</span><span class="value">待确认是否适用</span></div></div><p class="plain-note">要求齐备后：学员提交 → 法师查看资料、自检答案与分数、心得及实践记录 → 确认本课完成。</p></div>`,footer:foot('配套确认后可提交','submit-course','不会自动完成或开放下一门课程。',true)};}
// One node per course; actual assignments determine its position, never a preset syllabus.
function routeGroups(student='m1'){
 const groups={completed:[],current:[],planned:[]},selected=new Map(),rank=a=>['active','submitted'].includes(a.status)?3:a.status==='planned'?2:a.status==='completed'?1:0;
 for(const a of owned(student)){if(!rank(a))continue;const prior=selected.get(a.courseId);if(!prior||rank(a)>=rank(prior))selected.set(a.courseId,a);}
 for(const a of selected.values())groups[a.status==='completed'?'completed':a.status==='planned'?'planned':'current'].push(a);
 groups.completed.sort((a,b)=>(Date.parse(completionFact(b)?.at)||0)-(Date.parse(completionFact(a)?.at)||0));
 return groups;
}
function completionFact(a){return timeline(a.student).find(r=>r.kind==='completion'&&r.assignmentId===a.id);}
function routeDate(value){return dated(value)?T.dayKey(value).replaceAll('-','.'):'';}
function routeState(a){
 if(a.status==='completed')return completionFact(a)?.at?routeDate(completionFact(a).at)+' · 法师确认完成':'法师确认完成 · 日期未记录';
 if(a.status==='planned')return dated(a.scheduledAt)?routeDate(a.scheduledAt)+' · 计划开始':'法师已安排 · 开始时间未确认';
 if(a.status==='submitted')return '已提交，等待法师确认';
 const rows=timeline(a.student).filter(r=>r.assignmentId===a.id),guidance=rows.find(r=>r.kind==='guidance');
 if(guidance&&noticeItems(a.student).find(n=>n.recordId===guidance.id)?.unread)return '有新的法师指导';
 if(a.reflectionAt||rows.some(r=>r.kind==="reflection"))return '已保存心得与问题';
 if(rows.some(r=>r.kind==='study'&&r.page==='reflect'))return '已开始反思';
 if(rows.some(r=>r.kind==="timer"&&!r.demo))return "已保存修学计时";
 if(rows.some(r=>r.demo))return '已有演示阅读记录';
 return '已安排，待开始';
}
function routeNode(a){const c=courseById(a.courseId),comment=a.status==='completed'?completionFact(a)?.text:'',resume=resumeStudy(),last=a.student==='m1'&&resume.hasHistory&&resume.a?.id===a.id;return `<button class="course-route-node" data-go="course-progress" data-id="${esc(a.id)}"><span class="route-node-dot" aria-hidden="true">${a.status==='completed'?icon('check'):''}</span><span class="route-node-main"><span class="route-node-heading"><strong>${esc(c.title)}</strong><small>${esc(c.branch)}</small></span><span class="route-node-state">${last?'<span class="route-last-study">上次学习</span>':''}${esc(routeState(a))}</span>${comment?`<span class="route-node-comment">${esc(comment)}</span>`:''}</span>${icon('right')}</button>`;}
function courseRoute(student){const g=routeGroups(student);return `<p class="route-intro">沿着法师的安排，走好自己的修学路。</p><div class="personal-course-route"><section class="route-section route-completed" aria-label="已完成"><div class="route-section-title"><span class="route-section-mark" aria-hidden="true">${icon('check')}</span><h2>已完成</h2><small>${g.completed.length}门</small></div>${g.completed.length?g.completed.slice(0,2).map(routeNode).join(''):'<p class="route-empty">还没有经法师确认完成的课程。</p>'}${g.completed.length>2?`<details class="route-earlier"><summary>查看更早完成的 ${g.completed.length-2} 门</summary>${g.completed.slice(2).map(routeNode).join('')}</details>`:''}</section><section class="route-section route-current" aria-label="正在修学"><div class="route-section-title"><span class="route-section-mark" aria-hidden="true"></span><h2>正在修学</h2><small>${g.current.length}门${g.current.length>1?' · 可并行':''}</small></div>${g.current.length?g.current.map(routeNode).join(''):'<p class="route-empty">暂无进行中的课程，等待法师安排。</p>'}</section><section class="route-section route-planned" aria-label="后续安排"><div class="route-section-title"><span class="route-section-mark" aria-hidden="true"></span><h2>后续安排</h2>${g.planned.length?`<small>${g.planned.length}门</small>`:''}</div>${g.planned.length?g.planned.map(routeNode).join(''):'<p class="route-empty">暂无。后续由法师根据学习情况安排。</p>'}</section></div><p class="route-footnote">点课程查看详细进展。配套与完成要求待法师确认。</p><div class="route-secondary-links"><button class="text-button" data-action="all-history">详细学习记录 ${icon('right')}</button></div>`;}
function courseProgress(){
 const a=current(),c=courseById(a.courseId),rows=timeline(a.student).filter(r=>r.assignmentId===a.id),done=a.status==='completed',planned=a.status==='planned',readonly=done||planned,confirmation=completionFact(a),demo=data.tools.demoReadings[a.id],next=courseNext(a),actualTimers=rows.filter(r=>r.kind==='timer'&&!r.demo),wen=actualTimers.filter(r=>r.stage==='wen'),xiu=actualTimers.filter(r=>r.stage==='xiu');
 const assigned=routeDate(a.assignedAtISO||a.assignedAt),reflection=rows.find(r=>r.kind==='reflection'),savedReflection=reflection?reflection.text:a.reflectionAt?a.reflection:'',savedQuestion=reflection?reflection.question:a.reflectionAt?a.question:'';
 return {bar:header('课程进展','journey'),body:`<div class="pad course-progress-page"><p class="progress-category">${esc(c.branch)}课 · ${esc(done?'已完成':planned?'后续安排':'正在修学')}</p><h1 class="detail-title">${esc(c.title)}</h1><p class="progress-current-state">${esc(routeState(a))}</p>${assigned?`<p class="progress-assigned">${assigned} · 法师安排</p>`:''}${done?notice('法师已确认完成',confirmation?.text||'未记录确认说明。'):planned?notice('后续安排',dated(a.scheduledAt)?'计划于 '+routeDate(a.scheduledAt)+' 开始。具体学习要求按法师确认执行。':'开始时间与学习要求尚未确认。'):''}<section class="progress-guidance"><h2>法师指导</h2><p>${esc(a.guidance||'暂无具体指导。')}</p>${a.requirements?`<p>本次要求：${esc(a.requirements)}</p>`:''}</section>${!planned?`<section class="course-progress-stages" aria-label="闻思修进展"><div><span class="progress-stage-symbol">闻</span><div><h2>学习理论</h2><p>正式教材待接入，暂无教材完成进度。</p>${demo?`<p class="progress-fact">演示文章：停在第 ${demo.page+1} 节，仅记录阅读位置。</p>`:''}${wen.length?`<p class="progress-fact">已保存 ${wen.length} 次关联学习计时，不判定教材完成。</p>`:''}</div></div><div><span class="progress-stage-symbol">思</span><div><h2>自检与反思</h2><p>${c.checks.length?esc(c.checks.join('、'))+'：表单待接入。':'自检配套待法师确认。'}</p>${reflection||a.reflectionAt?`<p class="progress-fact">心得与问题已保存${reflection?.at?' · '+routeDate(reflection.at):''}</p>${savedReflection?`<p class="progress-reflection">${esc(savedReflection)}</p>`:''}${savedQuestion?`<p class="progress-reflection">想请教：${esc(savedQuestion)}</p>`:''}`:'<p>尚未保存心得与问题。</p>'}</div></div><div><span class="progress-stage-symbol">修</span><div><h2>配套实践</h2><p>是否适用、实践内容及要求待法师确认。</p>${xiu.length?`<p class="progress-fact">已保存 ${xiu.length} 次关联修习计时，不判定实践要求完成。</p>`:''}</div></div></section>`:''}<details class="progress-pending"><summary>查看待法师确认与待接入内容</summary>${list(definitionGaps(c))}</details><p class="progress-boundary">${done?'仅回看已有进展；复习权限待法师确认。':planned?'仅查看已安排信息，开始前不开放学习内容。':'待确认内容不计作你的未完成任务；演示阅读、时长和心得不代表结课。'}</p>${row('records','本课详细记录','查看安排、学习与指导的具体记录','path',`data-id="${esc(a.id)}" data-from="course-progress"`)}</div>`,footer:readonly?undefined:role==='teacher'?`<footer class="action-footer"><button class="primary" data-go="review" data-id="${esc(a.id)}">查看与指导</button></footer>`:`<footer class="action-footer"><button class="primary" data-action="course-next" data-id="${esc(a.id)}">${next.label}</button></footer>`};
}
function courseNext(a){
 if(['completed','planned'].includes(a.status))return {page:'course-progress',label:'查看课程进展',text:routeState(a)};
 if(a.status==='submitted')return {page:'task',label:'查看提交情况',text:'等待法师确认，可继续其他课程'};
 const guidance=timeline(a.student).find(r=>r.kind==='guidance'&&r.assignmentId===a.id);
 if(guidance&&noticeItems(a.student).find(n=>n.recordId===guidance.id)?.unread)return {record:guidance,label:'查看新指导',text:'法师更新了本课指导'};
 const position=actualStudyPosition(a);if(position)return {page:position.page,label:position.page==='article'?'继续演示阅读':'继续反思',text:position.page==='article'?'上次停在演示文章 · 正式教材待接入':'接着上次的心得与问题继续整理'};
 return {page:'read',label:'开始学习',text:'正式教材待接入 · 可体验演示阅读'};
}
function journey(){const student=role==='teacher'?activeStudent:'m1',historyView=ui.tab==='records';return {bar:header(historyView?'详细学习记录':'修学历程',role==='teacher'?'student':historyView?'home':null),body:`<div class="pad journey-page"><div class="journey-heading"><h1 class="page-heading">${historyView?'详细记录':role==='teacher'?esc(person(student).name)+'的修学路':'我的修学路'}</h1>${historyView?'<button class="text-button" data-action="back-route">返回路线</button>':''}</div>${historyView?historyPanel(student):courseRoute(student)}</div>`,bottom:bottom(role==='teacher'?'students':'journey')};}
function records(){const a=current(),c=courseById(a.courseId),rows=pathEntries(timeline(a.student)).filter(r=>r.assignmentId===a.id);return {bar:header('本课详细记录',ui.recordsFrom==='course-progress'?'course-progress':role==='teacher'?'review':'task'),body:`<div class="pad"><h1 class="detail-title">${esc(c.title)}</h1><p class="sub">${esc(c.branch)}课 · ${status(a)}</p>${rows.length?groupedHistory(rows):'<p class="plain-note">暂无心得或关联的计时记录。</p>'}<p class="plain-note">个人TXT试读与个人念佛次数在历程统一查看，不自动计入本课要求。</p><button class="text-button" data-action="view-history">前往详细记录 ${icon('right')}</button></div>`};}
function learning(){const arr=owned();return {bar:header('已安排课程','home'),body:`<div class="pad"><h1 class="page-heading">我的课程</h1><p class="sub space-top-sm">法师安排的课程同时保留，各课独立记录。</p>${arr.map(a=>row('task',courseById(a.courseId).title,branchOf(a)+'课 · '+status(a),'book',`data-id="${a.id}"`)).join('')}${!arr.length?'<div class="empty"><h2>暂无安排</h2><p>公共导读可先行查看。</p></div>':''}</div>`,bottom:bottom('home')};}
function sourceTree(items){return `<ul class="source-tree">${items.map(x=>`<li><span>${esc(x.title)}</span>${x.children?.length?sourceTree(x.children):''}</li>`).join('')}</ul>`;}
function guide(){return {bar:header('公共导读','home'),body:`<div class="pad"><h1 class="page-heading">导读</h1><p class="sub space-top-sm">公共开放 · 不计入四类24门</p>${MAP.publicGuide.children.map(g=>`<div class="unit-material-preview">${icon('book')}<span>${esc(g.title)}</span><small>资料待接入</small></div>`).join('')}${notice('导读资料待接入','目录公开可见，实际文件尚未接入。原导图中的数字不当作课时或完成指标。')}<div class="section-title"><h2>导读下的其他内容</h2></div>${MAP.introExtras.map(g=>`<div class="unit-material-preview">${icon('lock')}<span>${esc(g.title)}</span><small>配套范围待确认</small></div>`).join('')}<p class="plain-note">皈依、早晚定课、入门自检保留导图位置，不并入24门，不默认开放。</p></div>`,bottom:bottom('home')};}
function directory(){const teacher=role==='teacher';return {bar:header('原图行门目录',teacher?'assign':'home'),body:`<div class="pad"><h1 class="page-heading">行门内容保留</h1><p class="sub space-top-sm">用于课程配置阶段核对，不能在日常安排中逐项指派。</p>${teacher?`${MAP.sourceGroups.filter(g=>['正人','正信','正愿','正行'].includes(g.path)).map(g=>`<details class="source-group"><summary>${esc(g.path)} → ${esc(g.title)}</summary>${g.children?.length?sourceTree(g.children):'<p class="plain-note">具体表单与使用范围待确认。</p>'}<p class="source-note">随哪门课开放、是否共用以及完成要求，待法师确认；不默认绑定全部课程。</p></details>`).join('')}${notice('归属保留，不猜配','正信七信自检下的8个可见条目、正愿各类戒律、正行计数与助念等均保留。正行念佛总数仍为记录指标。')}`:notice('行门配套随课程开放','未安排的课程内容不会从此处开放。请从首页已安排课程进入。')}</div>`};}
function pending(){return {bar:header('待法师确认','assign'),body:`<div class="pad"><h1 class="page-heading">课程配套待确认</h1><p class="sub space-top-sm">先确认固定课程配置，再用于日常教学安排。</p>${list(MAP.pendingRules)}${notice('当前演示边界','24门课程可演示选择与安排；实际配套、资料、表单与完成规则未齐备，不能提交或确认完成。')}${row('directory','核对原图行门目录','完整保留，未指定的配套不自行绑定','list')}</div>`};}
function profile(){const teacher=role==='teacher';return {bar:header('我的',null),body:`<div class="pad"><div class="profile"><span class="avatar">${teacher?'慧':'心'}</span><div><h1>${teacher?'慧明法师':'明心'}</h1><p>${teacher?'法师端 · 修学指导':'学员端 · 法师指导修学'}</p></div></div>${teacher?row('students','我的学员','按个人情况安排课程','users')+row('pending','待确认的课程配套','7类问题，保留待确认状态','question'):row('learning','已安排课程','查看所有已开放课程','book')+row('guide','公共导读','认识体系与修学导图','leaf')+row('tools','阅读与修学工具','阅读器、个人计时、念佛计数','clock')}${row(teacher?'arrangement-history':'journey',teacher?'安排记录':'修学历程',teacher?'回看每位学员的课程安排':'回看已完成、正在修学与后续安排','path')}<button class="list-row" data-action="about"><span class="row-icon">${icon('question')}</span><span class="row-main"><strong>关于本次预览</strong><small>四类24门 · 配套待法师确认</small></span>${icon('right')}</button></div>`,bottom:bottom('profile')};}
function studentRows(){return students.filter(s=>!ui.search.trim()||s.name.includes(ui.search.trim())).map(s=>row('student',s.name,owned(s.id).length+'门已安排课程','user',`data-student="${s.id}"`)).join('')||'<div class="empty"><h2>未找到学员</h2></div>';}
function teacherHome(){return {bar:`<header class="app-bar"><div class="app-wordmark">${icon('lotus')}修学指导</div><button class="icon-btn" data-go="profile" aria-label="我的">${icon('user')}</button></header>`,body:`<div class="pad"><div class="greeting"><h1>我的学员</h1><p class="date">慧明法师 · 个人修学指导</p></div><label class="search">${icon('search')}<input id="student-search" placeholder="搜索学员法名" value="${esc(ui.search)}" aria-label="搜索学员"></label><div id="student-results">${studentRows()}</div>${notice('四类24门课程','课程内部固定组织正见与对应行门内容。当前配套待确认，安排仅用于流程演示。')}${row('pending','查看待确认配套','确认后固定，日常不逐项勾选','question')}</div>`,bottom:bottom('students')};}
function teacherStudent(){return {bar:header('学员修学','students'),body:`<div class="pad"><div class="profile"><span class="avatar">${person(activeStudent).initial}</span><div><h1>${person(activeStudent).name}</h1><p>多课并行 · 法师确认结课</p></div></div><button class="primary" data-go="assign">${icon('plus')} 安排课程</button>${row('journey','修学历程与学习记录','按个人实际安排展示','path')}${owned(activeStudent).map(a=>row('review',courseById(a.courseId).title,branchOf(a)+'课 · '+status(a),'book',`data-id="${a.id}"`)).join('')}${!owned(activeStudent).length?'<div class="empty"><h2>尚未安排课程</h2></div>':''}</div>`,bottom:bottom('students')};}
function assign(){const selected=ui.selected.filter(id=>courseById(id)&&!isOpened(courseById(id),activeStudent));const items=COURSES.filter(c=>ui.filter==='全部'||c.branch===ui.filter);return {bar:header('安排课程','student'),body:`<div class="pad"><h1 class="page-heading">给${person(activeStudent).name}安排课程</h1><p class="sub space-top-sm">选一门或多门，填写指导与要求。新增课程保留原有安排。</p><div class="course-counts">${['正人','正信','正愿','正行'].map(b=>`<span><b>${COURSES.filter(c=>c.branch===b).length}</b>${b}课</span>`).join('')}</div><div class="unit-filters" aria-label="课程分类">${['全部','正人','正信','正愿','正行'].map(b=>`<button class="chip ${ui.filter===b?'active':''}" data-action="course-filter" data-value="${b}" aria-pressed="${ui.filter===b}">${b}</button>`).join('')}</div><div class="section-title"><h2>固定课程目录</h2><span class="sub">共24门</span></div>${items.map(c=>`<div class="unit-choice"><label><input type="checkbox" name="assign-course" value="${c.id}" ${selected.includes(c.id)?'checked':''} ${isOpened(c,activeStudent)?'disabled':''}><span><strong>${esc(c.title)}</strong><small>${esc(c.branch)}课 · ${isOpened(c,activeStudent)?'已安排':'配套待法师确认'}</small></span></label><div class="unit-choice-foot"><span>正见＋对应行门</span><button class="text-button" data-go="course" data-course="${c.id}">查看配置 ${icon('right')}</button></div></div>`).join('')}${selected.length?`<div class="section-title"><h2>本次选择 ${selected.length}门</h2></div>${selected.map(id=>`<div class="selected-source"><span>${esc(courseById(id).branch)} · ${esc(courseById(id).title)}</span><button class="icon-btn" data-action="remove-course" data-course="${id}" aria-label="移除${esc(courseById(id).title)}">${icon('close')}</button></div>`).join('')}`:''}<div class="field"><label for="assign-guidance">本次指导</label><textarea id="assign-guidance" maxlength="1000" placeholder="填写给这位学员的指导">${esc(ui.guidance)}</textarea></div><div class="field"><label for="assign-requirements">本次要求</label><textarea id="assign-requirements" maxlength="1000" placeholder="填写学习安排与提醒，不替代待确认的固定课程规则">${esc(ui.requirements)}</textarea></div>${notice('演示安排 · 配套待确认','发布后学员可查看课程结构、保存心得与问题。固定配套仍待法师确认，不据此开放未确认表单、默认实践或判定完成。')}${row('pending','7类待法师确认的问题','不在本次安排时逐项猜配','question')}${row('directory','完整行门目录','仅供核对，不拆成日常指派小课','list')}${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}</div>`,footer:foot(selected.length?`发布${selected.length}门演示安排`:'请选择课程','publish-assignment','演示数据仅保存在本浏览器。',!selected.length)};}
function review(){const a=current(),c=courseById(a.courseId),reply=noticeItems(activeStudent).find(n=>n.assignmentId===a.id&&n.type==='reply'&&n.question===a.question);return {bar:header('查看课程学习','student'),body:`<div class="pad"><div class="breadcrumb">${person(a.student).name} · ${esc(c.branch)}课</div><h1 class="detail-title">${esc(c.title)}</h1>${tag(a)}<div class="guidance"><div class="guidance-head">本次指导</div><p>${esc(a.guidance)}</p>${a.requirements?`<p>本次要求：${esc(a.requirements)}</p>`:''}</div><button class="text-button" data-go="configure">修改本次指导与要求 ${icon('right')}</button><div class="section-title"><h2>学员心得</h2></div><p class="summary-prose">${esc(a.reflection)||'尚未保存心得。'}</p><div class="section-title"><h2>向法师请教</h2></div><p class="summary-prose">${esc(a.question)||'暂无问题。'}</p>${a.reflectionAt?`<p class="plain-note">保存时间：${esc(a.reflectionAt)}</p>`:''}${reply?`<div class="section-title"><h2>最近的回复</h2></div><p class="summary-prose">${esc(reply.reply)}</p>`:''}${pairing(c)}${notice('尚不可确认结课','实际资料进度、专项自检的答案与分数、实践记录及课程完成要求未齐备，不能确认完成。')}${row('course','查看固定课程配置','已明确对应与待确认配套','list',`data-course="${c.id}"`)}</div>`,footer:foot('配套补齐并提交后可确认','approve-course','心得保存与单次自检不等于课程完成。',true)};}
function configure(){const a=current(),draft=ui.configDraft?.id===a.id?ui.configDraft:{guidance:a.guidance,requirements:a.requirements,reply:''};return {bar:header('修改指导与要求','review'),body:`<div class="pad"><h1 class="detail-title">${esc(courseById(a.courseId).title)}</h1><p class="sub">只修改本次教学安排，固定课程配套仍按设计阶段确认结果。</p>${a.question?.trim()?`<div class="feedback-question"><strong>学员的问题</strong><p>${esc(a.question)}</p></div><div class="field"><label for="config-reply">回复这个问题（可选）</label><textarea id="config-reply" maxlength="1500" placeholder="保存后，学员会收到回复提醒">${esc(draft.reply)}</textarea></div>`:''}<div class="field"><label for="config-guidance">法师指导</label><textarea id="config-guidance" maxlength="1000">${esc(draft.guidance)}</textarea></div><div class="field"><label for="config-requirements">本次要求</label><textarea id="config-requirements" maxlength="1000">${esc(draft.requirements)}</textarea></div>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}${notice('固定配置不在日常指派时修改','不提供逐张选择自检、随意配置戒律或给所有课程添加实践的开关。')}</div>`,footer:foot('保存指导与回复','save-configuration')};}
function published(){const items=ui.published.map(id=>data.assignments.find(a=>a.id===id)).filter(Boolean);return {bar:header('课程已安排','student'),body:`<div class="pad"><div class="success-state"><div class="success-mark">${icon('check')}</div><h1>已为${person(activeStudent).name}安排</h1><p>新增安排已保留，原有课程不被覆盖。</p></div>${items.map(a=>row('review',courseById(a.courseId).title,'演示安排 · 配套待法师确认','book',`data-id="${a.id}"`)).join('')}${notice('待确认配套继续保留','学员可以查看课程结构、记录心得与问题。未接入的资料和表单不会生成已学完或评分。')}${row('student','查看学员全部安排','可继续安排其他课程','users')}</div>`};}
function historyPage(){return {bar:header('安排记录','students'),body:`<div class="pad"><h1 class="page-heading">历次课程安排</h1>${data.assignments.slice().reverse().map(a=>row('review',courseById(a.courseId).title,person(a.student).name+' · '+a.created+' · '+status(a),'book',`data-id="${a.id}"`)).join('')}</div>`,bottom:bottom('arrangement-history')};}
function duration(ms){const seconds=Math.floor(ms/1000);return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');}
function dateLabel(value){try{return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date(value));}catch{return String(value||'');}}
function dated(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}/.test(value)&&Number.isFinite(Date.parse(value));}
function timeline(student=role==='teacher'?activeStudent:'m1'){
 const assignments=owned(student),events=assignments.flatMap(a=>{
  const rows=[{id:'assignment-'+a.id,kind:'assignment',student,assignmentId:a.id,at:dated(a.assignedAtISO)?a.assignedAtISO:dated(a.assignedAt)?a.assignedAt:null,dateOnly:!dated(a.assignedAtISO),text:a.initialGuidance||'',requirements:a.initialRequirements||''}];
  (Array.isArray(a.events)?a.events:[]).forEach((e,i)=>{if(!['reflection','guidance','study'].includes(e.kind))return;const at=dated(e.atISO)?e.atISO:dated(e.at)?e.at:null;rows.push({id:'event-'+a.id+'-'+i,kind:e.kind,student,assignmentId:a.id,at,legacyTime:at?'':e.at||'',text:e.text,question:e.question,reply:e.reply,requirements:e.requirements,stage:e.stage,page:e.page,demo:e.demo===true});});
  if(a.status==='completed'){const e=(a.events||[]).filter(e=>['completion','completed'].includes(e.kind)).at(-1),at=e?.atISO||(dated(e?.at)?e.at:null)||a.confirmedAt||a.completedAt||null;rows.push({id:'completion-'+a.id,kind:'completion',student,assignmentId:a.id,at:dated(at)?at:null,text:e?.text||'',dateOnly:dated(at)&&at.length===10});}
  return rows;
 });
 return [...data.tools.records.filter(r=>r.student===student),...events].sort((a,b)=>(dated(b.at)?Date.parse(b.at):-Infinity)-(dated(a.at)?Date.parse(a.at):-Infinity)||a.id.localeCompare(b.id));
}
const pathKind=r=>r.kind==='assignment'?'assignment':r.kind==='completion'?'completion':r.kind==='guidance'?'guidance':r.kind==='chant'||r.kind==='timer'&&r.stage==='xiu'?'practice':'learning';
function noticeItems(student='m1'){return N.list(timeline(student),data.noticeSeen,student,data.planner.guidanceSeen);}
function markNoticeRead(item){
 if(role!=='student'||!item||!noticeItems().some(n=>n.token===item.token))return false;
 const before=JSON.parse(JSON.stringify(data.noticeSeen));if(!N.read(data.noticeSeen,item))return false;
 if(persist())return true;data.noticeSeen=before;ui.error='消息状态暂未保存，请重试。';return false;
}
function notices(){const items=noticeItems(),unread=items.filter(n=>n.unread).length;return {bar:header('修学消息','home'),body:`<div class="pad notifications-page"><h1 class="page-heading">法师安排与反馈</h1><p class="sub space-top-sm">${unread?unread+'条未读':'没有未读消息'}</p><div class="notice-list">${items.map(n=>`<button class="notice-entry ${n.unread?'unread':''}" data-action="open-notice" data-notice="${esc(n.token)}"><span class="notice-row-title"><strong>${n.type==='reply'?'法师回复了你的问题':n.kind==='guidance'?'法师更新了指导':'收到课程安排'}</strong>${n.unread?'<span class="notice-unread">未读</span>':''}</span><span class="notice-course">${esc(courseById(owned().find(a=>a.id===n.assignmentId)?.courseId)?.title||'关联课程')}</span>${n.reply||n.text?`<span class="notice-excerpt">${esc(n.reply||n.text)}</span>`:''}<time>${esc(n.at?n.dateOnly?T.dayKey(n.at)+' · 具体时刻未记录':dateLabel(n.at):n.legacyTime||'时间未记录')}</time>${icon('right')}</button>`).join('')}</div>${!items.length?'<div class="empty"><h2>暂时没有消息</h2><p>法师安排课程或保存指导后，会显示在这里。</p></div>':''}${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}<p class="plain-note">课程内容与完成要求仍以法师确认后的配置为准。</p></div>`};}
function saveGuidance(a,text,requirements,reply=''){
 if(role!=='teacher'||!a||a.student!==activeStudent)return false;
 text=String(text||'').trim();requirements=String(requirements||'').trim();reply=a.question?.trim()?String(reply||'').trim():'';
 if(!reply&&text===a.guidance&&requirements===a.requirements)return false;
 const before=JSON.parse(JSON.stringify(a));a.guidance=text;a.requirements=requirements;a.events=Array.isArray(a.events)?a.events:[];
 a.events.push({kind:'guidance',atISO:new Date().toISOString(),at:now(),text,requirements,...(reply?{reply,question:a.question}: {})});
 if(persist())return true;Object.keys(a).forEach(k=>delete a[k]);Object.assign(a,before);return false;
}
const pathLabel=r=>({assignment:'法师安排',learning:'学习',practice:'实践',guidance:'法师指导',completion:'法师确认完成'}[pathKind(r)]);
function pathEntries(all){return all.filter(r=>r.kind!=='reading'||!all.some(e=>e.id!==r.id&&dated(e.at)&&dated(r.at)&&T.dayKey(e.at)===T.dayKey(r.at)&&((r.demo&&e.demo&&e.assignmentId===r.assignmentId&&(e.kind==='study'&&e.page==='article'||e.kind==='timer'&&e.origin==='article'))||(!r.demo&&r.documentId&&e.kind==='timer'&&e.contentKey==='reader-'+r.documentId))));}
function matchesPath(r,filter){if(filter==='all')return true;if(['assignment','learning','practice','guidance','completion'].includes(filter))return pathKind(r)===filter;return recordKind(r)===filter||filter==='reflection'&&r.kind==='timer'&&r.reflection;}
const recordKind=r=>r.kind==='guidance'?'reflection':r.kind;
const stageLabel=value=>({wen:'闻',si:'思',xiu:'修'}[value]||'未标注环节');
function timerContext(r){if(r.demo)return (courseById(data.assignments.find(a=>a.id===r.assignmentId)?.courseId)?.title||'课程')+' · 闻（演示）';if(r.origin==='reader')return (r.contentTitle||'个人TXT试读')+' · 闻（个人）';return (r.assignmentId?courseById(data.assignments.find(a=>a.id===r.assignmentId)?.courseId)?.title||'关联课程':'个人修学')+' · '+stageLabel(r.stage);}
function timerDaySummary(student='m1',day=T.dayKey()){const total=T.dailyTimers(data.tools,day,student);return `<section class="daily-timer-summary" aria-label="每日修学计时累计"><div><span>${day===T.dayKey()?'今日':'当日'}修学计时</span><small>${total.count}次已保存</small></div><strong>${duration(total.seconds*1000)}</strong><p>${['wen','si','xiu'].map(k=>stageLabel(k)+' '+duration(total.byStage[k]*1000)).join('　')}${total.byStage.unmarked?' · 未标注 '+duration(total.byStage.unmarked*1000):''}</p>${total.demoCount?`<p class="demo-total-note">演示阅读另记 ${duration(total.demoSeconds*1000)} · 不计入上方累计</p>`:''}<small>按结束日期归档 · 暂停与未保存的时长不计入</small></section>`;}
function recordTitle(r){if(r.kind==='assignment')return '法师安排课程';if(r.kind==='completion')return '法师确认课程完成';if(r.kind==='study')return r.page==='article'?'进入演示文章阅读':'进入心得与反思';if(r.demo)return r.kind==='reading'?'演示文章阅读':'演示阅读计时';return {reading:'个人试读进度',timer:r.stage==='xiu'?'修习计时':'学习计时',chant:'念佛计数',reflection:'心得与问题',guidance:'法师指导与要求'}[r.kind]||'学习记录';}
function recordDescription(r){const title=courseById(data.assignments.find(a=>a.id===r.assignmentId)?.courseId)?.title||'课程';if(r.kind==='assignment')return title+' · 由法师安排';if(r.kind==='completion')return title+' · 已有确认完成记录';if(r.kind==='study')return title+' · '+stageLabel(r.stage)+(r.demo?'（演示）':'');if(r.kind==='reading')return `${r.name} · 第${r.page}/${r.pageCount}页 · ${r.bookmarkCount}个书签`;if(r.kind==='timer')return duration(r.seconds*1000)+' · '+timerContext(r)+(r.adjusted?' · 已调整':'')+(r.reflection?' · 有心得':'');if(r.kind==='chant')return `${r.amount}次 · 个人记录`;return (courseById(data.assignments.find(a=>a.id===r.assignmentId)?.courseId)?.title||'课程')+' · '+(r.kind==='guidance'?'调整指导':'已保存心得／问题');}
function eventTime(r){if(!dated(r.at))return r.legacyTime||'时间未记录';if(r.dateOnly)return '具体时刻未记录';try{return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date(r.at));}catch{return '时间未记录';}}
function historyRows(rows){return rows.map(r=>`<button class="history-entry path-event" data-go="record-detail" data-record="${esc(r.id)}"><span class="path-event-dot">${icon({assignment:'book',learning:'edit',practice:'lotus',guidance:'note',completion:'check'}[pathKind(r)])}</span><span><span class="path-event-meta"><span>${pathLabel(r)}${r.demo?' · 演示':''}</span><time>${esc(eventTime(r))}</time></span><strong>${recordTitle(r)}</strong><small>${esc(recordDescription(r))}</small>${r.text?`<p class="path-event-excerpt">${esc(r.text)}</p>`:''}</span>${icon('right')}</button>`).join('');}
function groupedHistory(rows){const groups=[];for(const r of rows){const day=dated(r.at)?T.dayKey(r.at):'';let g=groups.find(g=>g.day===day);if(!g){g={day,rows:[]};groups.push(g);}g.rows.push(r);}return groups.map(g=>`<section class="path-day" aria-label="${g.day||'日期未完整记录'}"><h2>${g.day||'日期未完整记录'}</h2><div class="path-events">${historyRows(g.rows)}</div></section>`).join('');}
function historyPanel(student){const all=pathEntries(timeline(student)),dayRows=ui.historyDay?all.filter(r=>dated(r.at)&&T.dayKey(r.at)===ui.historyDay):all,rows=dayRows.filter(r=>matchesPath(r,ui.recordFilter));const emptyTitles={assignment:'暂无课程安排记录',learning:'暂无学习记录',practice:'暂无实践记录',guidance:'暂无法师指导更新',completion:'暂无法师确认完成记录'};return `<div class="history-date"><label for="history-day">日期</label><input id="history-day" type="date" value="${esc(ui.historyDay)}"><button class="text-button" data-action="history-today">今天</button><button class="text-button" data-action="history-all-days">全部</button></div><div class="history-filters" aria-label="路径事件类型">${[['all','全部'],['assignment','安排'],['learning','学习'],['practice','实践'],['guidance','指导'],['completion','完成']].map(([v,label])=>`<button class="chip ${ui.recordFilter===v?'active':''}" data-action="record-filter" data-value="${v}" aria-pressed="${ui.recordFilter===v}">${label}</button>`).join('')}</div><p class="path-order">${ui.historyDay?esc(ui.historyDay):'全部日期'} · 最近在前</p>${groupedHistory(rows)}${!rows.length?`<div class="empty"><h2>${emptyTitles[ui.recordFilter]||'暂无这类记录'}</h2><p>${ui.recordFilter==='completion'?'课程经法师实际确认后，才会出现在这里。':'可切换日期或类型；只显示已发生的记录。'}</p></div>`:''}${ui.historyDay?`<details class="path-daily-totals"><summary>查看当日时长累计</summary>${timerDaySummary(student,ui.historyDay)}</details>`:''}<p class="plain-note">只记录实际发生的安排、学习、实践、指导和完成，不设统一晋级阶段。演示阅读单独标注；时长、次数不自动生成课程完成。</p>`;}
function recordDetail(){const r=timeline().find(r=>r.id===ui.recordId);return {bar:header('学习记录详情',ui.recordFrom),body:`<div class="pad">${r?`<h1 class="detail-title">${recordTitle(r)}</h1><p class="sub">${esc(dated(r.at)?(r.dateOnly?T.dayKey(r.at)+' · 具体时刻未记录':dateLabel(r.at)):r.legacyTime||'时间未记录')}</p><p class="record-detail-main">${esc(recordDescription(r))}</p>${r.demo?notice('原型演示记录','来自通用阅读样稿，不作为正式教材学习进度或课程完成依据。'):r.kind==='reading'?notice('个人TXT试读','这里只保存该文件最近阅读位置与书签数量，不代表已读完课程教材。'):r.kind==='timer'?notice('学习时长记录','关联课程只用于整理记录，不作为该课学完或完成的判定。'):r.kind==='chant'?notice('个人念佛次数','未预设目标，不自动计入任何未确认的课程配套。'):''}${r.demo&&['study','timer'].includes(r.kind)?(()=>{const progress=timeline().find(p=>p.kind==='reading'&&p.demo&&p.assignmentId===r.assignmentId);return progress?`<p class="plain-note">最近阅读位置：${esc(progress.name)} · 第${progress.page}/${progress.pageCount}节 · ${progress.bookmarkCount}个书签</p>`:'';})():''}${r.kind==='timer'?`<dl class="timer-record-meta"><div><dt>计时时长</dt><dd>${duration((r.measuredSeconds??r.seconds)*1000)}</dd></div><div><dt>记录方式</dt><dd>${r.adjusted?'手动调整':r.source==='auto'?'自动计时':'手动计时'}</dd></div></dl>${r.adjusted?`<p class="summary-prose">调整说明：${esc(r.adjustmentReason)}</p>`:''}`:''}${r.text||r.reflection?`<div class="section-title"><h2>${r.kind==='guidance'?'指导':r.kind==='assignment'?'安排时的指导':r.kind==='completion'?'确认说明':'心得'}</h2></div><p class="summary-prose">${esc(r.reflection||r.text)}</p>`:''}${r.reply?`<div class="section-title"><h2>法师回复</h2></div><p class="summary-prose">${esc(r.reply)}</p>`:''}${r.question?`<div class="section-title"><h2>${r.kind==='guidance'?'对应的问题':'问题'}</h2></div><p class="summary-prose">${esc(r.question)}</p>`:''}${r.requirements?`<p class="summary-prose">本次要求：${esc(r.requirements)}</p>`:''}${r.assignmentId?row('course-progress','查看关联课程','回看该课内容与法师指导','book',`data-id="${esc(r.assignmentId)}"`):''}`:notice('未找到这条记录','该记录不存在或不属于当前查看的学员。')}</div>`,footer:foot(ui.recordFrom==='notices'?'返回消息':'返回详细记录','back-history')};}
function tools(){const timer=data.tools.timer;return {bar:header('阅读与修学工具','profile'),body:`<div class="pad"><h1 class="page-heading">修学工具</h1><p class="sub space-top-sm">记录实际使用，回到历程统一查看。</p>${row('reader','阅读器',data.tools.reader.document?'继续个人TXT试读 · '+data.tools.reader.document.name:'课程教材待接入 · 可导入个人TXT试读','book')}${row('timer','个人计时',timer?(timer.status==='running'?'正在计时':'已暂停')+' · '+duration(T.elapsed(data.tools)):'独立修习 · 手动开始与结束','clock')}${row('counter','念佛计数',data.tools.counter.count?'本次尚未保存 '+data.tools.counter.count+'次':'个人次数记录 · 不预设目标','lotus')}<button class="list-row" data-action="view-history"><span class="row-icon">${icon('path')}</span><span class="row-main"><strong>查看学习记录</strong><small>阅读、计时、念佛与心得</small></span>${icon('right')}</button>${notice('教材与配套继续待确认','个人试读和辅助工具不替代实际教材，不自动给课程配置实践或完成标准。')}</div>`,bottom:bottom('profile')};}
// Content identity survives a settings panel or a hidden tab; activity does not.
function contentContext(){if(role!=='student')return null;const a=current();if(page==='article'&&a?.student==='m1'&&a.status==='active'&&data.tools.demoReadings[a.id])return {assignmentId:a.id,stage:'wen',key:'demo-article-'+a.id,origin:'article',title:DEMO_ARTICLE.title,demo:true};if(page==='reflect'&&a?.student==='m1'&&a.status==='active')return {assignmentId:a.id,stage:'si',key:'reflection-'+a.id,origin:'reflect'};const d=data.tools.reader.document;if(page==='reader'&&d?.text?.trim())return {assignmentId:null,stage:'wen',key:'reader-'+d.id,origin:'reader',title:d.name};return null;}
function learningContext(){return document.hidden||isReaderPanel()?null:contentContext();}
function readingDuration(seconds){if(seconds<1)return '不足1秒';const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return `${h?h+'小时':''}${m?m+'分':''}${s?s+'秒':''}`;}
function syncLearningTimer(){
 const context=contentContext(),s=data.tools.timer,at=Date.now();let finished=false;
 if(s?.source==='auto'&&['article','reader','reflect'].includes(s.origin)&&!s.review&&!s.draftReview&&s.contentKey!==context?.key){
  const reflecting=s.origin==='reflect',label=reflecting?'反思':'阅读';
  if(reflecting&&!flushReflection(owned().find(a=>a.id===s.assignmentId))){T.pause(data.tools,at);persist();setToast('心得与时长暂未保存，请返回反思页面重试。',5000);return false;}
  const before=JSON.parse(JSON.stringify(data.tools)),result=T.finishAuto(data.tools,at);
  if(result){
   if(!persist()){T.pause(before,at);before.timer.pauseReason='navigation';before.timer.lastActiveAt=at;data.tools=before;setToast(`${label}时长暂未保存，请返回内容后重试。`,5000);return false;}
   finished=true;setToast(`本次${label}${readingDuration(result.seconds)}${result.record?'，已记录':'，未生成计时记录'}`,4500);
  }
 }
 const changed=T.syncAuto(data.tools,learningContext(),at);if(changed)persist();return finished||changed;
}
function timerRibbon(){const s=data.tools.timer,ctx=contentContext();if(role!=='student'||!s||['timer','timer-review','timer-saved'].includes(page))return '';const active=s.source==='auto'&&ctx?.key===s.contentKey;if(active&&['article','reader','reflect'].includes(s.origin)&&!s.review&&!s.draftReview)return `<div class="auto-timer-ribbon"><div class="reading-duration">${icon('clock')}<span>本次${s.origin==='reflect'?'反思':'阅读'}</span><b data-timer-display role="timer" aria-label="本次${s.origin==='reflect'?'反思':'阅读'}时长">${duration(T.elapsed(data.tools))}</b></div></div>`;return `<div class="auto-timer-ribbon"><button class="timer-ribbon" data-go="timer">${icon('clock')}<span>${esc(timerContext(s))} · ${s.status==='running'?'计时中':'已暂停'}</span><b data-timer-display>${duration(T.elapsed(data.tools))}</b>${icon('right')}</button>${active?`<div class="auto-timer-controls"><button data-action="${s.status==='running'?'pause-timer':'resume-auto'}">${s.status==='running'?'暂停计时':'继续计时'}</button><button data-action="end-timer">结束并记录</button></div>`:ctx?'<p class="timer-conflict">另有一条计时未结束，当前内容暂不计时。请先处理已有记录。</p>':''}</div>`;}
function returnToTimedContent(){const s=data.tools.timer;if(!s||s.source!=='auto')return;if(s.status==='paused')s.pauseReason='navigation';if(s.review){s.draftReview=s.review;delete s.review;}if(s.draftReview)T.start(data.tools);persist();navigate(s.origin==='article'?'article':s.origin==='reader'?'reader':'reflect',{id:s.assignmentId});}
function timer(){const s=data.tools.timer,stage=s?s.stage:ui.timerStage;return {bar:header(s?.source==='auto'?'学习计时状态':'个人计时','tools'),body:`<div class="pad"><p class="sub">${s?.source==='auto'?'返回实际内容继续学习':'独立个人修习，手动开始与结束'}</p><div class="study-timer"><span>${s?s.status==='running'?'正在计时':'已暂停':'准备开始'}</span><strong data-timer-display role="timer" aria-label="学习时长">${duration(T.elapsed(data.tools))}</strong><p>${s?esc(timerContext(s)):'选择本次个人修习环节'}</p></div>${s?`<p class="plain-note">${esc(timerContext(s))} · ${s.source==='auto'?'实际内容自动计时':'手动计时'}</p>`:'<p class="plain-note">本次为个人修习，不自动绑定课程要求。</p>'}<fieldset class="timer-stage"><legend>本次环节</legend>${[['wen','闻','学习理论'],['si','思','自检反思'],['xiu','修','实际修习']].map(([v,label,desc])=>`<label><input type="radio" name="timer-stage" value="${v}" ${stage===v?'checked':''} ${s?'disabled':''}><span><b>${label}</b><small>${desc}</small></span></label>`).join('')}</fieldset>${s&&!s.stage?'<p class="plain-note">这是旧版暂存计时，环节保留未标注。</p>':''}${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}${s?`<div class="tool-action-row">${primary(s.status==='running'?'暂停':s.source==='auto'?'返回内容继续':'继续计时',s.status==='running'?'pause-timer':s.source==='auto'?'resume-auto':'start-timer')}<button class="secondary" data-action="end-timer">结束并记录</button></div><button class="text-button tool-discard" data-action="discard-timer">放弃本次计时</button>`:primary(stage==='xiu'?'开始修习':'开始个人计时','start-timer')}<p class="plain-note">${s?.source==='auto'?'自动计时只累计实际内容停留；离开或切到后台即暂停。':'个人计时可在切页后继续，结束时请手动确认。'}教材、修习配套及完成要求仍待确认，暂不设置番茄钟循环。</p>${timerDaySummary()}<button class="list-row" data-action="view-history"><span class="row-main"><strong>查看计时记录</strong><small>统一保存在历程的学习记录中</small></span>${icon('right')}</button></div>`};}
function timerReview(){const s=data.tools.timer,review=s?.review;if(!review)return {bar:header('结束确认','timer'),body:`<div class="pad">${notice('没有待确认的计时','请返回修学计时开始，或到历程查看已保存记录。')}${row('timer','返回修学计时','开始或继续一次修学','clock')}</div>`};const n=Math.max(0,review.seconds);return {bar:`<header class="app-bar"><button class="back" data-go="timer" aria-label="返回计时">${icon('left')}</button><div class="bar-title">结束确认</div><span></span></header>`,body:`<div class="pad timer-review"><h1 class="page-heading">记录这次修学</h1><p class="sub space-top-sm">${esc(timerContext(s))}</p><p class="timer-measured">计时已暂停 · 实际计时 ${duration(review.measuredSeconds*1000)}</p><div class="field"><label>本次记录时长</label><div class="duration-fields">${[['hours','小时',Math.floor(n/3600),999],['minutes','分钟',Math.floor(n/60)%60,59],['seconds','秒',n%60,59]].map(([key,label,value,max])=>`<label><input id="timer-${key}" type="number" inputmode="numeric" min="0" max="${max}" value="${esc(review.fields?.[key]??value)}" aria-label="记录${label}"><span>${label}</span></label>`).join('')}</div><p class="plain-note">忘记暂停时可按实际修正。计时原值会保留。</p></div><div class="field"><label for="timer-reason">调整说明 <small>修改时长后必填</small></label><input id="timer-reason" maxlength="300" value="${esc(review.adjustmentReason)}" placeholder="例如：忘记暂停，扣除离开时间"></div><div class="field"><label for="timer-reflection">本次心得 <small>选填</small></label><textarea id="timer-reflection" maxlength="1500" placeholder="记录一句观察，或留空直接保存">${esc(review.reflection)}</textarea></div>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}<p class="plain-note">心得随本次计时一起保存，不覆盖课程原有心得。记录时长不代表课程完成，课程要求仍待法师确认。</p></div>`,footer:foot('确认保存到历程','confirm-timer','不填心得也能保存。')};}
function timerSaved(){const r=timeline('m1').find(r=>r.id===ui.recordId&&r.kind==='timer');return {bar:header('修学已记录','journey'),body:`<div class="pad">${r?`<div class="success-state"><div class="success-mark">${icon('check')}</div><h1>本次修学已记录</h1><p>${esc(timerContext(r))}</p></div><p class="saved-timer-duration">${duration(r.seconds*1000)}</p><p class="plain-note center">${r.reflection?'心得已随本次计时保存':'本次未填写心得，时长已正常保存'}${r.adjusted?' · 时长已手动调整':''}</p>${timerDaySummary('m1',T.dayKey(r.at))}${row('record-detail','回看本次记录','课程、环节、时长与心得','note',`data-record="${esc(r.id)}"`)}<button class="text-button" data-action="continue-after-timer">继续学习 ${icon('right')}</button><p class="plain-note">仅保存过程记录。真实教材与课程完成要求仍待确认。</p>`:notice('未找到本次记录','可前往历程查看已保存内容。')}</div>`,footer:foot('查看历程','timer-history')};}
function counter(){const c=data.tools.counter;return {bar:header('念佛计数','tools'),body:`<div class="pad"><div class="counter-heading"><h1 class="page-heading">记录本次念佛</h1><p class="sub">个人辅助记录 · 不预设次数目标</p></div><div class="counter-area"><button class="count-button" data-action="chant-one" aria-label="念佛计数增加一次">${icon('lotus')}<strong>${c.count}</strong><small>点击记录一次</small></button><div class="count-tools"><button data-action="chant-undo" ${c.undo.length?'':'disabled'}>撤销上次</button><button data-action="chant-ten">+10</button></div></div><div class="field"><label for="chant-manual">补记实际次数</label><div class="chant-manual"><input id="chant-manual" type="number" min="1" max="1000000" inputmode="numeric" placeholder="填写要补记的次数"><button class="small-primary" data-action="chant-manual">加入本次</button></div></div><p class="plain-note">本次数量会暂存，切换页面或刷新可继续。保存后归入历程，再开始下一次。</p><div class="tool-action-row">${primary('保存本次次数','save-chant',!c.count)}<button class="secondary" data-action="clear-chant" ${c.count?'':'disabled'}>清空本次</button></div><p class="plain-note">课程中的念佛配套及完成要求仍待法师确认。本工具仅保存个人次数，不自动计入课程要求。</p><button class="text-button" data-action="view-history">查看学习记录 ${icon('right')}</button>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}</div>`};}
function reader(){const d=data.tools.reader.document,pages=d?T.pages(d.text):[];return {bar:header('阅读器 · 个人试读',ui.readerBack),body:`<div class="pad reader-tool"><p class="reader-origin">课程教材尚未接入 · 个人TXT不计入课程教材进度</p><div class="reader-file-actions"><label class="import-text-button">${icon('plus')}${d?'导入其他TXT':'导入本地TXT试读'}<input id="reader-file" type="file" accept=".txt,text/plain"></label>${d?`<button class="text-button" data-action="remove-reader">移除试读</button>`:''}</div>${d?`<h1 class="reader-title">${esc(d.name)}</h1><article class="personal-reader-paper" style="${readerTextStyle()}">${esc(pages[d.page])}</article><p class="plain-note">自动保存阅读位置与书签；这里只记录浏览位置，不判定已读完。</p>`:`<div class="reader-missing">${icon('book')}<h1>暂无可阅读正文</h1><p>课程教材和目录仍待接入。<br>可导入自己的TXT体验阅读与排版设置。</p><small>文件只保存在当前浏览器，不上传。支持UTF-8文本，文件最多500KB。</small></div>`}<button class="text-button" data-action="view-history">查看阅读记录 ${icon('right')}</button>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}</div>`,footer:d?readerFooter(d.page,pages.length,false):undefined};}
function captureTimerReview(){const review=data.tools.timer?.review;if(!review)return;const inputs=['hours','minutes','seconds'].map(k=>$('#timer-'+k));if(inputs.some(e=>!e))return;review.fields=Object.fromEntries(['hours','minutes','seconds'].map((k,i)=>[k,inputs[i].value]));const values=inputs.map(e=>e.value.trim()===''?NaN:Number(e.value));review.seconds=values.every((v,i)=>Number.isInteger(v)&&v>=0&&v<=(i===0?999:59))?values[0]*3600+values[1]*60+values[2]:-1;review.adjustmentReason=$('#timer-reason')?.value||'';review.reflection=$('#timer-reflection')?.value||'';}
function updateTimerDisplay(){document.querySelectorAll('[data-timer-display]').forEach(e=>e.textContent=duration(T.elapsed(data.tools)));}
function saveToolMutation(mutate){const before=JSON.parse(JSON.stringify(data.tools));const result=mutate();if(!persist()){data.tools=before;ui.error='浏览器保存失败，本次内容仍保留，请释放空间后重试。';render(true);return false;}return result;}
function openHistory(kind='all'){ui.tab='records';ui.recordFilter=({reading:'learning',chant:'practice',reflection:'learning',timer:'all'}[kind]||kind);navigate('journey');}

const links=()=>role==='teacher'?[['students','users','我的学员'],['student','user','学员修学'],['assign','plus','安排24门课程'],['review','book','查看课程学习'],['pending','question','待法师确认'],['directory','list','原图行门目录'],['arrangement-history','clock','安排记录'],['profile','user','我的']]:[['home','home','今日修学'],['task','book','本课闻思修'],['learning','list','已安排课程'],['tools','clock','阅读与修学工具'],['journey','path','历程与记录'],['guide','leaf','公共导读'],['profile','user','我的']];
function sidebar(){return `<aside class="preview-sidebar"><div class="preview-brand"><div class="brand-mark">${icon('lotus')}</div><div><strong>人间净土</strong><p>四类24门 · 手机交互原型</p></div></div><div class="role-switch" aria-label="预览角色"><button data-role="student" class="${role==='student'?'active':''}">学员端</button><button data-role="teacher" class="${role==='teacher'?'active':''}">法师端</button></div><div class="side-heading">页面导航</div><nav class="preview-links">${links().map(([to,ic,label])=>`<button data-go="${to}" class="${page===to?'active':''}">${icon(ic)}${label}</button>`).join('')}</nav><div class="preview-note">人物与安排为演示。<br>课程依据《五正课程设计初稿》。<br>${recovery?'本地数据无法读取，重置演示后可保存。':storageError?'保存未成功，请保留页面并重试。':'操作仅保存在本浏览器，刷新可继续。'}</div><div class="side-actions"><button data-action="design-rules">课程规则</button><button data-action="reset-demo">重置示例</button></div></aside>`;}
function pageInfo(){const map={notices:['法师安排与反馈','只展示实际保存的课程安排、指导和问题回复，点开后标记已读。'],'course-progress':['每门课的实际进展','闻思修的已有记录、法师指导和待确认配套放在课程内。时长与演示阅读不代表完成。'],article:['演示文章体验正式阅读流程','进入正文自动记录演示阅读时长，支持目录、书签与阅读设置。样稿不是本课正式教材，教材与配套继续待确认。'],tools:['工具记录统一归入历程','阅读器可导入个人TXT，计时可跨页恢复，念佛仅记录个人次数。缺失教材与未确认配套继续标明。'],reader:['个人试读与课程教材分开','实际教材未接入。个人TXT提供翻页、字号、行距、背景和书签，位置记录不能作为课程完成依据。'],timer:['个人计时与学习状态','课程内不再先启动计时。实际阅读与反思自动计时，个人修习仍手动开始。缺失内容占位页不计时。'],reflect:['实际反思自动计时','反思内容自动暂存，离开时记录实际时长；切后台暂停。专项自检表与完成要求仍待接入确认。'],counter:['个人念佛次数','点按、撤销与补记会暂存；保存后进入历程。没有默认次数目标，也不自动绑定课程配套。'],home:['按类别找课，继续上次学习','五瓣莲花直接进入类别详情；继续学习独立记住上次实际进入的课程与环节。'],category:['类别详情呈现对应课程','已安排课程优先，未安排课程保留锁定。正见汇总已开放课程的理论，不另建一套课程。'],assign:['按完整课程安排','正人8门、正信7门、正愿2门、正行7门。先确认固定配套，再用于日常安排；当前发布为演示。'],course:['正见与行门组成一门课','理论路径、已明确对应、待法师确认的配套分开展示。不把资料和表单拆成日常逐项指派的小课。'],think:['自检、心得与问题归思','保存心得可以与配套确认并行。未接入实际表单，不生成通用题、分数或完成记录。'],journey:['走好自己的修学路','已完成、正在修学、后续安排，每门课一个节点。点开看详细进展；多门课程可并行，后续只展示法师已明确的安排。'],review:['由法师确认完成','资料进度、自检答案与分数、心得和实践记录齐备后才能判断完成。当前缺口继续保留。'],directory:['完整保留行门目录','按原图归属留存，不自行配给某门课，不因为24门包装删除内容。'],practice:['不强加独立实践','实践配套与要求待法师确认，不预设念佛、拜佛或助念。没有独立实践的课程不强行添加修。']};return map[page]||['课程结构已调整','四类24门＋公共导读。多课并行，学员提交、法师确认；未知配套和真实资料缺口明确标注。'];}
function modal(){if(!ui.modal)return '';let title=ui.infoTitle,body=`<p>${esc(ui.infoBody)}</p>`,buttons=primary('知道了','close-modal');if(isReaderPanel()){title=ui.modal==='reader-settings'?'阅读设置':ui.modal==='reader-bookmarks'?'书签':page==='article'?'目录':'页码跳转';body=ui.modal==='reader-settings'?readerSettingsPanel():readerNavigationPanel(ui.modal==='reader-bookmarks');buttons='';}if(ui.modal==='timer-discard'){title='放弃本次计时';body='<p>本次尚未保存的时长将被清除，已有记录不受影响。</p>';buttons=`<div class="sheet-actions">${primary('保留本次','close-modal')}${primary('确认放弃','confirm-discard-timer')}</div>`;}if(ui.modal==='counter-clear'){title='清空本次次数';body='<p>仅清空本次尚未保存的次数，历程中已有记录会保留。</p>';buttons=`<div class="sheet-actions">${primary('保留本次','close-modal')}${primary('确认清空','confirm-clear-chant')}</div>`;}if(ui.modal==='reader-remove'){title='移除个人试读';body='<p>移除当前浏览器中的试读正文与书签，原始TXT文件不受影响。历程保留已产生的阅读位置记录。</p>';buttons=`<div class="sheet-actions">${primary('保留试读','close-modal')}${primary('确认移除','confirm-remove-reader')}</div>`;}if(ui.modal==='reset'){title='重置本版演示';body='<p>恢复24门课程版初始安排，清除本版心得和定课设置。旧版v4记录仍保存在旧存储键中。</p>';buttons=`<div class="sheet-actions">${primary('取消','close-modal')}${primary('重置示例','confirm-reset')}</div>`;}if(ui.modal==='pages'){title='切换页面';body=`<div class="role-switch"><button data-role="student">学员端</button><button data-role="teacher">法师端</button></div><nav class="preview-links">${links().map(([to,ic,label])=>`<button data-go="${to}">${icon(ic)}${label}</button>`).join('')}</nav>`;body+='<div class="side-actions"><button data-action="design-rules">课程规则</button><button data-action="reset-demo">重置示例</button></div>';buttons='';}return `<div class="modal" data-action="modal-backdrop"><section class="sheet ${isReaderPanel()?'reader-sheet':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="sheet-head"><h2 id="dialog-title" tabindex="-1">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${body}${buttons}</section></div>`;}
function render(preserve=false){cancelLotusNavigation();const focusId=ui.modal&&document.activeElement?.closest?.('.sheet')?document.activeElement.id:null;const scroll=preserve?$('.phone-content')?.scrollTop||0:readingScrollTop();const views={home,notices,category,tools,reader,article,reflect,timer,'timer-review':timerReview,'timer-saved':timerSaved,counter,'course-progress':courseProgress,'record-detail':recordDetail,course,task,read,think,practice,submit,journey,records,learning,guide,directory,pending,profile,students:teacherHome,student:teacherStudent,assign,review,configure,published,'arrangement-history':historyPage};const view=views[page](),[title,desc]=pageInfo();$('#app').innerHTML=`<div class="mobile-tools"><span class="mini-brand">人间净土 · 24门课程原型</span><button data-action="page-menu">${role==='teacher'?'法师端':'学员端'} · 页面导航</button></div><main class="preview">${sidebar()}<div class="phone-wrap"><section class="phone ${page==='article'||page==='reader'&&data.tools.reader.document?'reader-theme-'+data.tools.reader.theme:''}" aria-label="${role==='teacher'?'法师':'学员'}端手机原型">${statusBar()}<div class="phone-viewport">${view.bar||''}${timerRibbon()}<div class="phone-content" id="screen-content">${view.body}</div>${view.footer||''}${view.bottom||''}${ui.toast?`<div class="toast" role="status">${esc(ui.toast)}</div>`:''}${modal()}</div><div class="gesture" aria-hidden="true"></div></section></div><aside class="preview-context"><div class="context-line"></div><h2>${title}</h2><p>${desc}</p><div class="flow-index">${['法师选课安排','闻 · 讲解资料','思 · 自检与反思','修 · 适用的实践','提交 · 法师确认'].map((v,i)=>`<span class="${i===(page==='read'?1:page==='think'?2:page==='practice'?3:['submit','review'].includes(page)?4:0)?'active':''}"><i>${i+1}</i>${v}</span>`).join('')}</div><p class="scope-note">课程设计：正人8门＋正信7门＋正愿2门＋正行7门。公共导读单独保留。配套先由法师确认后固定；当前不编造资料、题目或完成标准。</p></aside></main>`;$('.phone-content').scrollTo({top:scroll,behavior:'instant'});if(ui.modal){document.querySelectorAll('.phone-content,.bottom-nav,.app-bar,.action-footer,.reader-footer,.auto-timer-ribbon').forEach(e=>e.inert=true);requestAnimationFrame(()=>{const target=focusId?document.getElementById(focusId):null;(target&&!target.disabled?target:$('#dialog-title'))?.focus();});}scalePhone();}
function scalePhone(){const wide=innerWidth>1080,side=innerWidth>700,w=side?innerWidth-(wide?609:318):innerWidth-36,h=innerHeight-(side?54:76);document.documentElement.style.setProperty('--phone-scale',Math.max(.35,Math.min(1,w/413,h/852)).toFixed(4));}
function now(){return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date());}
function publishCourses(ids,student,guidance,requirements){const at=new Date(),assignedAtISO=at.toISOString(),assignedAt=T.dayKey(assignedAtISO),displayDate=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',timeZone:'Asia/Shanghai'}).format(at);const selected=[...new Set(ids)].filter(id=>courseById(id)&&!isOpened(courseById(id),student));const created=selected.map((id,i)=>newAssignment(id,student,'course-'+Date.now()+'-'+i,{assignedAtISO,assignedAt,created:displayDate,guidance:guidance.trim()||'请按本课已确认内容修学，有问题可记录后向法师请教。',requirements:requirements.trim()}));data.assignments.push(...created);return created;}
function commitPlanner(mutate){const before=JSON.parse(JSON.stringify(data.planner)),result=mutate();if(typeof result==='string'&&result){ui.error=result;render(true);return false;}if(result===false){ui.error='这项操作目前不可用，请返回重试。';render(true);return false;}if(!persist()){data.planner=before;ui.error='浏览器保存失败，请释放空间后重试；原有记录已保留。';render(true);return false;}ui.error='';return true;}
const actions={
 'open-reader-panel':btn=>{if(!['article','reader'].includes(page)||!['settings','directory','bookmarks'].includes(btn.dataset.panel))return;ui.modal='reader-'+btn.dataset.panel;ui.error='';syncLearningTimer();render(true);},
 'reader-preference':btn=>{const key=btn.dataset.setting,value=['fontSize','lineHeight'].includes(key)?Number(btn.dataset.value):btn.dataset.value;if(saveToolMutation(()=>T.setReaderPreference(data.tools,key,value))){ui.error='';render(true);}},
 'reset-reader-preferences':()=>{if(saveToolMutation(()=>T.resetReaderPreferences(data.tools))){ui.error='';render(true);}},
 'toggle-reader-bookmark':()=>{if(page==='article'){const a=current();saveToolMutation(()=>T.bookmarkDemo(data.tools,a.id,DEMO_ARTICLE.title,DEMO_ARTICLE.pages.length));}else saveToolMutation(()=>T.bookmark(data.tools));render(true);},
 'all-history':()=>{ui.tab='records';ui.historyDay='';ui.recordFilter='all';navigate('journey');},
 'back-route':()=>{ui.tab='path';navigate('journey');},
 'course-next':btn=>{const a=owned().find(a=>a.id===btn.dataset.id);if(!a||!['active','submitted'].includes(a.status))return;const next=courseNext(a);activeId=a.id;if(next.record){const item=noticeItems().find(n=>n.recordId===next.record.id);if(!item||!markNoticeRead(item))return;navigate('record-detail',{record:next.record.id});}else navigate(next.page,{id:a.id});},
 'article-reflect':()=>{if(page==='article')navigate('reflect');},
 'article-turn':btn=>{const a=current();if(page!=='article'||!a)return;if(saveToolMutation(()=>{const turned=T.turnDemo(data.tools,a.id,Number(btn.dataset.page),DEMO_ARTICLE.title,DEMO_ARTICLE.pages.length);if(turned)data.tools.demoReadings[a.id].scrollTop=0;return turned;}))finishReaderJump();},
 'article-bookmark':()=>{const a=current();if(page!=='article'||!a)return;saveToolMutation(()=>T.bookmarkDemo(data.tools,a.id,DEMO_ARTICLE.title,DEMO_ARTICLE.pages.length));render(true);},
 'history-all-days':()=>{ui.historyDay='';history.replaceState(navigationState(),'',url());render();},
 'course-path':btn=>{activeId=btn.dataset.id;navigate('records',{id:btn.dataset.id});},
 'history-today':()=>{ui.historyDay=T.dayKey();history.replaceState(navigationState(),'',url());render();},
 'timer-history':()=>{const r=timeline().find(r=>r.id===ui.recordId);if(r)ui.historyDay=T.dayKey(r.at);openHistory('timer');},
 'continue-after-timer':()=>{const r=timeline().find(r=>r.id===ui.recordId),a=owned().find(a=>a.id===r?.assignmentId);if(r?.origin==='article'&&a)navigate('article',{id:a.id});else if(r?.origin==='reader')navigate('reader');else if(a)navigate(r?.origin==='reflect'?'reflect':{wen:'read',si:'think',xiu:'practice'}[r.stage]||'task',{id:a.id});else navigate('tools');},
 'record-filter':btn=>{ui.recordFilter=btn.dataset.value;history.replaceState(navigationState(),'',url());render();},
 'view-history':()=>openHistory(),
 'back-history':()=>{ui.tab='records';navigate(ui.recordFrom);},
 'resume-auto':()=>{returnToTimedContent();},
 'start-practice':()=>openInfo('实践配套待确认','本课没有已确认的实践内容，暂不启动修习或计时。'),
 'start-timer':()=>{if(role!=='student')return;if(data.tools.timer?.source==='auto'){returnToTimedContent();return;}const stage=$('input[name="timer-stage"]:checked')?.value||ui.timerStage;if(!data.tools.timer&&!['wen','si','xiu'].includes(stage)){ui.error='请选择本次的闻、思或修环节。';render(true);return;}if(saveToolMutation(()=>T.start(data.tools,null,Date.now(),stage))){ui.error='';render();}},
 'pause-timer':()=>{saveToolMutation(()=>T.userPause(data.tools));render(true);},
 'end-timer':()=>{if(saveToolMutation(()=>T.prepareTimerEnd(data.tools)))navigate('timer-review');},
 'confirm-timer':()=>{if(role!=='student'||data.tools.timer?.status!=='paused'||!data.tools.timer?.review)return;captureTimerReview();const error=T.timerReviewError(data.tools.timer.review);if(error){ui.error=error;render(true);return;}const r=saveToolMutation(()=>T.saveTimer(data.tools));if(r){ui.historyDay=T.dayKey(r.at);navigate('timer-saved',{record:r.id});}},
 'discard-timer':()=>{T.pause(data.tools);persist();ui.modal='timer-discard';render(true);},
 'confirm-discard-timer':()=>{if(saveToolMutation(()=>{data.tools.timer=null;return true;})){ui.modal=null;ui.timerScope='';ui.timerStage='';render();}},
 'chant-one':()=>{T.addCount(data.tools,1);persist();render(true);},
 'chant-ten':()=>{T.addCount(data.tools,10);persist();render(true);},
 'chant-undo':()=>{T.undoCount(data.tools);persist();render(true);},
 'chant-manual':()=>{const n=Number($('#chant-manual')?.value);if(!T.addCount(data.tools,n)){ui.error='请填写1至1000000的整数，本次累计不超过10000000。';render(true);return;}ui.error='';persist();render(true);},
 'save-chant':()=>{const r=saveToolMutation(()=>T.saveCount(data.tools));if(r){ui.historyDay=T.dayKey(r.at);openHistory('chant');}},
 'clear-chant':()=>{ui.modal='counter-clear';render(true);},
 'confirm-clear-chant':()=>{if(saveToolMutation(()=>{data.tools.counter.count=0;data.tools.counter.undo=[];return true;})){ui.modal=null;render(true);}},
 'text-prev':()=>{const d=data.tools.reader.document;if(d&&T.turn(data.tools,d.page-1)){d.scrollTop=0;persist();render();}},
 'text-next':()=>{const d=data.tools.reader.document;if(d&&T.turn(data.tools,d.page+1)){d.scrollTop=0;persist();render();}},
 'reader-bookmark':()=>{T.bookmark(data.tools);persist();render(true);},
 'reader-bookmark-jump':btn=>{if(T.turn(data.tools,Number(btn.dataset.page))){data.tools.reader.document.scrollTop=0;persist();finishReaderJump();}},
 'reader-jump':()=>{const n=Number($('#reader-jump')?.value);if(!T.turn(data.tools,n-1)){ui.error='请输入当前文本范围内的整数页码。';render(true);return;}data.tools.reader.document.scrollTop=0;ui.error='';persist();finishReaderJump();},
 'remove-reader':()=>{ui.modal='reader-remove';render(true);},
 'confirm-remove-reader':()=>{if(saveToolMutation(()=>{data.tools.reader.document=null;return true;})){ui.modal=null;syncLearningTimer();render();}},

 'notices':()=>navigate('notices'),
 'open-notice':btn=>{const item=noticeItems().find(n=>n.token===btn.dataset.notice);if(!item)return;if(!markNoticeRead(item)){render(true);return;}ui.recordFrom='notices';navigate('record-detail',{record:item.recordId});},
 'design-rules':()=>openInfo('课程设计规则','24门是课程安排粒度，不是修学阶段。每门包含正见与固定行门配套；先经法师确认，再用于日常安排。公共导读独立。所有未定配套、真实资料和完成规则继续标注。'),
 'about':()=>openInfo('24门课程交互原型','依据《五正课程设计初稿》。仅本地演示，无真实账户与云端服务。原始导图资料、自检表、评分及回向文本未接入。旧v4演示保留在原存储键，本版不自动迁移旧小单元。'),
 'page-menu':()=>{ui.modal='pages';render(true);},
 'close-modal':()=>closeModal(),
 'reset-demo':()=>{ui.modal='reset';render(true);},
 'confirm-reset':()=>{data=seed();recovery=false;ui.selected=[];ui.published=[];ui.categoryBranch='正信';ui.taskFrom='home';ui.readFrom='task';ui.courseFrom='home';activeId='karma';activeStudent='m1';persist();navigate(role==='teacher'?'students':'home');},
 'return-task':()=>learningBackPages.includes(page)?returnToEntry('task'):navigate('task'),'return-category':()=>page==='read'?returnToEntry('category'):navigate('category'),'open-submit':()=>navigate('submit'),
 'save-reflection':()=>{if(role==='student'&&page==='reflect')returnToEntry(ui.reflectFrom);},
 'journey-tab':btn=>{ui.tab=btn.dataset.value;history.replaceState(navigationState(),'',url());render();},
 'course-filter':btn=>{ui.filter=btn.dataset.value;render(true);},
 'remove-course':btn=>{ui.selected=ui.selected.filter(id=>id!==btn.dataset.course);render(true);},
 'choose-course':()=>{if(role!=='teacher'||isOpened(courseById(courseId),activeStudent))return;ui.selected=[...new Set([...ui.selected,courseId])];navigate('assign');},
 'publish-assignment':()=>{if(role!=='teacher')return;const created=publishCourses(ui.selected,activeStudent,ui.guidance,ui.requirements);if(!created.length)return;ui.published=created.map(a=>a.id);ui.selected=[];ui.guidance='';ui.requirements='';persist();navigate('published');},
 'save-configuration':()=>{if(role!=='teacher')return;const a=current(),draft={id:a.id,guidance:$('#config-guidance').value.trim(),requirements:$('#config-requirements').value.trim(),reply:$('#config-reply')?.value.trim()||''};ui.configDraft=draft;if(!draft.reply&&draft.guidance===a.guidance&&draft.requirements===a.requirements){ui.configDraft=null;navigate('review');flash('没有修改，本次未新增提醒');return;}if(!saveGuidance(a,draft.guidance,draft.requirements,draft.reply)){ui.error='暂未保存，请保留内容并重试。';render(true);return;}ui.configDraft=null;navigate('review');flash(draft.reply?'指导与回复已保存，学员将看到提醒':'本次指导已保存，学员将看到提醒');},
 'submit-course':()=>{if(!canSubmit(current()))openInfo('暂不可提交','固定课程配置、实际资料与完成要求未齐备。');},
 'approve-course':()=>{if(!canSubmit(current()))openInfo('暂不可确认','需要真实学习记录、明确完成要求和学员提交。');},
};
document.addEventListener('click',event=>{const lotusEntry=event.target.closest('[data-lotus-entry]');if(lotusEntry){activateLotus(lotusEntry);return;}const roleBtn=event.target.closest('[data-role]');if(roleBtn){switchRole(roleBtn.dataset.role);return;}const go=event.target.closest('[data-go]');if(go){if(go.disabled)return;if(go.hasAttribute('data-history-back')){returnToEntry(go.dataset.go);return;}const id=go.dataset.id;if(id&&role==='teacher'){const a=data.assignments.find(a=>a.id===id);if(a)activeStudent=a.student;}navigate(go.dataset.go,{id,student:go.dataset.student,course:go.dataset.course,branch:go.dataset.branch,from:go.dataset.from,record:go.dataset.record,scope:go.dataset.scope,stage:go.dataset.stage});return;}const btn=event.target.closest('[data-action]');if(!btn||btn.disabled)return;if(btn.dataset.action==='modal-backdrop'){if(event.target===btn)closeModal();return;}actions[btn.dataset.action]?.(btn);});
document.addEventListener('input',event=>{const e=event.target;if(['timer-hours','timer-minutes','timer-seconds','timer-reason','timer-reflection'].includes(e.id)){captureTimerReview();persist();}if(e.name==='timer-stage'){ui.timerStage=e.value;const start=$('[data-action="start-timer"]');if(start&&!data.tools.timer)start.textContent=e.value==='xiu'?'开始修习':'开始个人计时';}if(['config-guidance','config-requirements','config-reply'].includes(e.id)&&role==='teacher'){const a=current();ui.configDraft={id:a.id,guidance:$('#config-guidance')?.value||'',requirements:$('#config-requirements')?.value||'',reply:$('#config-reply')?.value||''};}if(e.id==='assign-guidance')ui.guidance=e.value;if(e.id==='assign-requirements')ui.requirements=e.value;if(['reflection','question'].includes(e.id)&&role==='student'&&page==='reflect'){const a=current();a.reflectionDraft={...reflectionValues(a),[e.id==='reflection'?'text':'question']:e.value};const saved=persist(),status=$('#reflection-save-status');if(status)status.textContent=saved?'草稿已暂存本机':'草稿暂存失败，请保留页面并重试';}if(e.id==='timer-scope')ui.timerScope=e.value;if(e.id==='student-search'){ui.search=e.value;$('#student-results').innerHTML=studentRows();}});
document.addEventListener('change',async event=>{const e=event.target;
 if(e.id==='history-day'&&/^\d{4}-\d{2}-\d{2}$/.test(e.value)){ui.historyDay=e.value;history.replaceState(navigationState(),'',url());render();return;}
 if(e.id==='reader-file'){const file=e.files?.[0];if(!file)return;if(!/\.txt$/i.test(file.name)||file.size>500*1024){ui.error='请导入500KB以内的UTF-8 TXT文件。';render(true);return;}try{const text=await file.text();const r=saveToolMutation(()=>T.importText(data.tools,file.name,text));if(r){ui.error='';syncLearningTimer();render();}}catch(error){ui.error=error.message||'文件读取失败，请重试。';render(true);}return;}
if(e.name==='assign-course'){ui.selected=e.checked?[...new Set([...ui.selected,e.value])]:ui.selected.filter(id=>id!==e.value);render(true);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&pendingLotus){cancelLotusNavigation();return;}const petal=event.target.closest?.('svg [role="button"]');if(petal&&['Enter',' '].includes(event.key)){event.preventDefault();petal.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}if(!ui.modal)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const nodes=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input,.sheet textarea,.sheet select')],first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement?.id==='dialog-title')){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
addEventListener('resize',scalePhone);
function onRoutePopState(event){backPending=false;if(restoringHistory){restoringHistory=false;render(true);return;}const previous=url(),target=navigationEntry(event.state?.zenNavigation);if(!leaveContent()){if(target?.session===navEntry.session&&target.index!==navEntry.index){restoringHistory=true;history.go(navEntry.index-target.index);}else{history.replaceState(navigationState(),'',previous);}return;}navEntry=target||{session:Date.now().toString(36)+Math.random().toString(36).slice(2),index:0,scrollTop:0};params=routeParams();role=params.get('role')==='teacher'?'teacher':'student';page=params.get('page')||(role==='teacher'?'students':'home');activeStudent=params.get('student')||'m1';activeId=params.get('task')||'karma';courseId=params.get('course')||'karma';ui.taskFrom=parentPage(params.get('taskFrom')||params.get('from'));ui.courseFrom=['category','task'].includes(params.get('from'))?params.get('from'):params.get('courseFrom')==='category'?'category':'home';ui.readFrom=params.get('from')==='category'?'category':'task';ui.categoryBranch=validBranch(params.get('branch'));ui.recordId=params.get('record')||'';ui.articleFrom=contentParent(params.get('articleFrom'),'read');ui.reflectFrom=contentParent(params.get('reflectFrom'),'think');ui.timerScope=params.get('scope')||'';ui.timerStage=params.get('stage')||'';ui.historyDay=params.get('day')||'';ui.recordsFrom=params.get('recordsFrom')==='course-progress'?'course-progress':'';ui.recordFrom=['records','course-progress','notices'].includes(params.get('recordFrom'))?params.get('recordFrom'):'journey';ui.tab=params.get('tab')==='records'?'records':'path';ui.recordFilter=['all','assignment','learning','practice','guidance','completion','reading','timer','chant','reflection'].includes(params.get('filter'))?params.get('filter'):'all';normalizeRoute();ui.modal=null;ui.error='';if(role==='student'&&recordStudy(current(),page))persist();prepareArticle();syncLearningTimer();render();if(!['article','reader'].includes(page))$('.phone-content')?.scrollTo({top:navEntry.scrollTop||0,behavior:'instant'});}
addEventListener('popstate',onRoutePopState);
